var e={AnimationOptions:`Das Timing einer Animation. Was weggelassen wird, behält den Standardwert dieser Animation.`,"AnimationOptions.duration":"In ms. Standard 200 für Layout-Bewegungen, 250 für den Drop; `0` schaltet die Animation aus.","AnimationOptions.easing":"Ein CSS-Easing (`'ease-out'`, `cubic-bezier(…)`).",LayoutAnimationContext:`Was eine Layout-Animationsfunktion erhält, für ein Element, das an seinen neuen Platz zieht.`,"LayoutAnimationContext.key":`Schlüssel des Elements.`,"LayoutAnimationContext.element":`Das DOM-Element des Elements, bereits an seinem neuen Platz.`,"LayoutAnimationContext.from":`Sichtbares Rechteck vor der Änderung (wo eine laufende Animation das Element gezeigt hat).`,"LayoutAnimationContext.to":`Layout-Rechteck nach der Änderung.`,"LayoutAnimationContext.options":`Das Timing aus den Optionen, mit eingesetzten Standardwerten.`,"LayoutAnimationContext.reason":"Was das Element bewegt hat: ein Drag (`'drag'`: Sortieren, der Drop, ein Abbruch) oder eine Änderung deiner Daten, die kein Drag ausgelöst hat (`'change'`, bei eingeschaltetem `animateChanges` der Liste).","LayoutAnimationContext.signal":"Wird abgebrochen, wenn die Bibliothek die Animation unterbricht: Das Element bewegt sich erneut, bevor sie endet (die nächste Animation beginnt dort, wo es gezeigt wird), oder Animationen werden ausgeschaltet. Eine zurückgegebene `Animation` wird für dich abgebrochen. Stoppe hier alles andere und mache die Styles, die es gesetzt hat, sofort rückgängig: Das Layout wird direkt danach gemessen.","LayoutAnimationContext.reducedMotion":"`prefers-reduced-motion: reduce` ist gesetzt. Die eigenen Animationen der Bibliothek laufen dann nicht; deine Funktionen laufen immer und entscheiden anhand dieses Werts (überspringen oder eine Überblendung beibehalten).",LayoutAnimation:"Wie Elemente an ihre neuen Plätze gelangen: `true` (Standard-Timing), Optionen, `false` (sie springen) oder eine Funktion, die ein Element von `from` nach `to` animiert und seine `Animation` zurückgibt, ein Promise, das abgeschlossen ist, wenn sie endet, oder nichts.",DropAnimationContext:`Was eine Drop-Animationsfunktion erhält: das Overlay, wo es ist und wo es landet.`,"DropAnimationContext.overlay":"Die Box des Overlays; sie landet im Slot des aktiven Elements. Bei einem Multi-Drag landen die Klone der anderen Elemente, die darin mitfahren (die des Standard-Overlays, die `DragPreview`s eines eigenen), von selbst in ihren eigenen Slots (mit dem Standard-Timing, wenn dies eine eigene Funktion ist).","DropAnimationContext.from":`Wo das Overlay ist, wenn der Drag endet.`,"DropAnimationContext.to":"Endgültiges Rechteck des abgelegten Elements; `null`, wenn es nicht gerendert oder nicht sichtbar ist (das Overlay wird ausgeblendet).","DropAnimationContext.into":`Das Element ist nach einem Drop auf eine Drop-Zone (keine sortierbare Liste) nicht zu sehen, z. B. wurde es in ein anderes Element (einen Ordner) oder eine Papierkorb-Zone abgelegt: das sichtbare Rechteck der Zone. Die Standardanimation lässt das Overlay beim Ausblenden in dieses Rechteck schrumpfen, statt es an Ort und Stelle auszublenden.`,"DropAnimationContext.reason":"`'drop'`: Das Overlay landet dort, wo der Drop das Element abgelegt hat. `'cancel'`: Es fliegt dorthin zurück, wo das Element war.","DropAnimationContext.active":`Der beendete Drag.`,"DropAnimationContext.over":"Das Ziel, auf dem der Drop landet (eine Liste, eine Zone); `null` beim Abbrechen.","DropAnimationContext.options":`Das Timing aus den Optionen, mit eingesetzten Standardwerten.`,"DropAnimationContext.reducedMotion":"`prefers-reduced-motion: reduce` ist gesetzt. Die eigenen Animationen der Bibliothek laufen dann nicht; deine Funktionen laufen immer und entscheiden anhand dieses Werts (überspringen oder eine Überblendung beibehalten).",DropAnimation:"Wie das Overlay bei einem Drop landet und bei einem Abbruch zurückfliegt: `true` (Standard-Timing), Optionen, `false` (kein Flug: Es endet dort, wo es losgelassen wurde) oder eine Funktion, die `overlay` von `from` nach `to` animiert und seine `Animation` zurückgibt, ein Promise, das abgeschlossen ist, wenn sie endet, oder nichts.",EnterAnimationContext:"Ein Element, das in einer Liste mit eingeschaltetem `animateChanges` erschienen ist: hinzugefügt oder wieder eingeblendet (ein Filter, ein aufgeklappter Baumknoten).","EnterAnimationContext.key":`Schlüssel des Elements.`,"EnterAnimationContext.element":`Das DOM-Element des Elements, bereits an seinem Platz.`,"EnterAnimationContext.to":`Wo es erschienen ist (Layout-Rechteck).`,"EnterAnimationContext.options":`Das Timing aus den Optionen, mit eingesetzten Standardwerten.`,"EnterAnimationContext.reducedMotion":"`prefers-reduced-motion: reduce` ist gesetzt. Die eigenen Animationen der Bibliothek laufen dann nicht; deine Funktionen laufen immer und entscheiden anhand dieses Werts (überspringen oder eine Überblendung beibehalten).",LeaveAnimationContext:"Ein Element, das eine Liste mit eingeschaltetem `animateChanges` verlassen hat: entfernt oder ausgeblendet (ein Filter, ein zugeklappter Baumknoten).","LeaveAnimationContext.key":`Schlüssel des Elements.`,"LeaveAnimationContext.element":"Eine Kopie des DOM-Elements, gezeigt dort, wo das Element war (das Element selbst ist weg): absolut positioniert in seinem alten Elternelement, für den Zeiger nicht erreichbar, markiert mit `data-dnd-leaving`. Die Bibliothek entfernt sie, wenn deine Animation endet.","LeaveAnimationContext.from":`Wo das Element war.`,"LeaveAnimationContext.options":`Das Timing aus den Optionen, mit eingesetzten Standardwerten.`,"LeaveAnimationContext.reducedMotion":"`prefers-reduced-motion: reduce` ist gesetzt. Die eigenen Animationen der Bibliothek laufen dann nicht; deine Funktionen laufen immer und entscheiden anhand dieses Werts (überspringen oder eine Überblendung beibehalten).",EnterAnimation:"`true`, Optionen, `false` (das Element erscheint einfach) oder eine Funktion, die sein Erscheinen animiert.",LeaveAnimation:"`true`, Optionen, `false` (das Element verschwindet einfach) oder eine Funktion, die das Verschwinden der an seinem Platz zurückgelassenen Kopie animiert: Gib ihre `Animation` oder ein Promise zurück, und die Kopie wird entfernt, wenn sie endet (sofort, wenn die Funktion nichts zurückgibt).",AutoAnimationOptions:"`animateChanges` mit seinen Teilen: `duration` und `easing` für alle, und pro Art von Änderung `true`, Optionen (über den gemeinsamen), `false` oder eine eigene Funktion.","AutoAnimationOptions.move":"Elemente, die ihren Platz gewechselt haben (das Standard-FLIP, wie bei `animation`; eine Funktion ersetzt es).","AutoAnimationOptions.enter":`Erschienene Elemente. Standard: Sie werden an ihrem Platz eingeblendet.`,"AutoAnimationOptions.leave":`Verschwundene Elemente. Standard: Eine Kopie des Elements wird dort ausgeblendet, wo es war, und schrumpft dabei ein wenig.`,AutoAnimation:"Animiert Änderungen an den Elementen einer Liste (oder eines Baums), die kein Drag ausgelöst hat: hinzugefügte, entfernte, verschobene (eine Sortierung, ein Mischen, ein Verschieben zwischen Listen einer Gruppe) oder gefilterte Elemente. Standardmäßig aus (`false`); `true` animiert Verschiebungen sowie erscheinende und verschwindende Elemente mit dem Standard-Timing. Drags behalten ihre eigenen Animationen (`animation`, `dropAnimation`). Mit `prefers-reduced-motion: reduce` laufen die Standardanimationen nicht; deine Funktionen laufen trotzdem (mit `reducedMotion: true`). Nur Elemente in der Nähe des sichtbaren Bereichs werden animiert (nicht gemountete Zeilen einer virtuellen Liste werden übersprungen).",DragAreaOptions:"Optionen von `makeDragArea`: Regeln für die Drags, die innerhalb des Elements des Bereichs beginnen (ziehbare wie sortierbare Elemente), sodass ein einziger Provider die ganze App bedienen kann, während Teile der Seite auf ihre eigene Weise ziehen. Bei verschachtelten Bereichen gewinnt der nächstgelegene.\n\nJede Option nimmt einen Wert, ein Ref oder einen Getter entgegen und wird gelesen, wenn sie gebraucht wird: wenn ein Druck beginnt (`activation`, `disabled`) oder wenn der Drag beginnt.","DragAreaOptions.axis":"Beschränkt die Drags auf eine Achse, nach den Modifiern. Das eigene `axis` eines ziehbaren Elements (oder das seiner Liste) gewinnt.","DragAreaOptions.modifiers":"Modifier für die Drags, nach denen des Providers und vor den eigenen des ziehbaren Elements (oder denen seiner Liste): z. B. `[snapToGrid(20)]` für ein Board.","DragAreaOptions.restrictToArea":"`true`: Die Drags bleiben innerhalb des Elements des Bereichs (nach den Modifiern, vor der Achsensperre).","DragAreaOptions.autoScroll":"Überschreibt `autoScroll` des Providers für den Scroll-Container des Bereichs: das Element selbst oder seinen nächsten scrollbaren Vorfahren. `false` schaltet es dort aus. Anders als die anderen Optionen gilt es für jeden Drag, der den Container scrollt, egal wo er begonnen hat.","DragAreaOptions.activation":`Aktivierung der Drags pro Zeigerart, zwischen der eigenen des ziehbaren Elements (die gewinnt) und der des Providers: z. B. ein längeres Drücken per Touch in einem scrollenden Feed.`,"DragAreaOptions.disabled":"`true`: Kein Drag beginnt im Bereich, auch nicht in den Bereichen darin (anders als bei den anderen Optionen, die vom nächstgelegenen Bereich kommen). Seine ziehbaren Elemente melden `aria-disabled`.",DragAreaReturn:"Was `makeDragArea` zurückgibt.","DragAreaReturn.isDragging":`Ein Drag, der in diesem Bereich begonnen hat, läuft (bis über seinen Drop entschieden ist).`,"DragAreaReturn.isAutoScrolling":`Auto-Scroll bewegt den Scroll-Container des Bereichs (das Element oder seinen nächsten scrollbaren Vorfahren).`,CollisionCandidate:`Ein Drop-Ziel, das eine Kollisionserkennung auswählen kann: aktiviert, auf der Seite und nicht vollständig abgeschnitten.`,"CollisionCandidate.id":`ID des Drop-Ziels.`,"CollisionCandidate.rect":`Sichtbarer Teil des Ziels: beschnitten durch seine Scroll-Container und den Viewport.`,"CollisionCandidate.priority":"Die `priority` des Ziels (Standard 0): Der höhere Wert gewinnt, wenn sich Ziele ohne Verschachtelung überlappen. Sortierbare Elemente schlagen Container.","CollisionCandidate.depth":`Verschachtelungsebene unter den Drop-Zielen: 0 ganz oben, tiefere Ziele haben höhere Werte.`,CollisionArgs:`Was eine Kollisionserkennung bei jeder Bewegung des Drags erhält.`,"CollisionArgs.pointer":`Zeiger in Viewport-Koordinaten, nach den Modifiern.`,"CollisionArgs.overlayRect":"Rechteck der gezogenen Box (das Overlay oder das Element selbst bei `overlay: false`) dort, wohin der Drag sie bewegt hat.","CollisionArgs.candidates":"Jedes Drop-Ziel, zu dem der Drag gehen könnte, ob seine `accept`-Regel den Drag annimmt oder nicht.","CollisionArgs.hits":`Drop-Ziele unter dem Zeiger aus dem Hit-Testing (berücksichtigt z-Reihenfolge und Shadow Roots), das beste zuerst.`,CollisionDetection:`Gibt die IDs der Kandidaten zurück, den besten zuerst.`,ModifierArgs:`Was ein Modifier bei jeder Bewegung des Drags erhält.`,"ModifierArgs.transform":`Versatz seit dem Start des Drags, wie ihn die vorherigen Modifier verändert haben.`,"ModifierArgs.active":`Der Drag.`,"ModifierArgs.activeRect":`Rechteck des gezogenen Elements beim Start des Drags.`,"ModifierArgs.overlayRect":"Rechteck der Overlay-Box, wenn sie um `transform` verschoben würde, in ihrer jetzigen Größe. Mit `overlayFit: 'slot'` ändert die Box ihre Größe um den Zeiger herum, daher ist sie nicht immer `activeRect`, verschoben um `transform`.","ModifierArgs.origin":`Position des Zeigers beim Start des Drags.`,"ModifierArgs.containerRect":`Container der sortierbaren Liste (oder Elternelement) des gezogenen Elements, dort, wo er jetzt ist (er folgt dem Scrollen).`,"ModifierArgs.containerShift":`Wie weit sich der Inhalt, in dem der Drag gestartet ist, seit dem Start auf dem Bildschirm bewegt hat: Der Container hat sich bewegt (die Seite oder ein Container um ihn herum wurde gescrollt, das Layout hat sich verschoben), und sein Inhalt wurde in ihm gescrollt. Achsensperren halten die andere Achse dort, sodass der Drag in seiner Zeile oder Spalte dieses Inhalts bleibt.`,"ModifierArgs.windowRect":`Rechteck des Fensters (der Viewport).`,"ModifierArgs.over":"Das Drop-Ziel unter dem Drag, wie zuletzt gefunden; `null` über nichts.",Modifier:"Ändert, wohin das gezogene Element geht: nimmt den Versatz des Drags (`transform`) und gibt einen neuen zurück.",SnapToGridOptions:"Optionen von `snapToGrid`.","SnapToGridOptions.x":`Die Breite der Zelle in px. Ohne sie (oder bei 0) bewegt sich der Drag frei entlang x.`,"SnapToGridOptions.y":"Die Höhe der Zelle in px. Ohne sie (oder bei 0) bewegt sich der Drag frei entlang y: `{ y: 15 }` rastet nur die Uhrzeit eines Kalendertermins ein.","SnapToGridOptions.origin":"`'container'` (Standard): Die obere linke Ecke des Overlays landet auf Rasterlinien, die von der oberen linken Ecke des Containers aus gezogen werden (`containerRect`: die sortierbare Liste oder das Elternelement). `'delta'`: Der Versatz des Drags wird gerundet, sodass die Startposition des Elements außerhalb des Rasters erhalten bleibt.","SnapToGridOptions.smooth":`Lässt das Overlay zwischen eingerasteten Positionen gleiten (Standard 80 ms). Die Kollisionserkennung nutzt trotzdem sofort die eingerastete Position.`,DragItem:`Ein gezogenes Element: das, von dem der Drag ausging, oder ein weiteres eines Multi-Drags.`,"DragItem.id":`ID seines ziehbaren Elements (der Schlüssel eines sortierbaren Elements).`,"DragItem.item":`Objekt des Elements, wenn der Drag aus einer sortierbaren Liste kommt.`,"DragItem.data":"Seine Option `data`.","DragItem.label":"Sein `label`, der lesbare Name.","DragItem.type":"Normalisierter `type` des ziehbaren Elements; leer bedeutet, dass es zu jedem Drop-Ziel passt.",Active:`Der laufende Drag: das Element, von dem er ausging, und jedes Element, das er trägt.`,"Active.id":`ID des Elements, bei dem der Drag begonnen hat.`,"Active.ids":`Alle gezogenen IDs, die primäre zuerst (Multi-Drag).`,"Active.items":`Jedes gezogene Element, das primäre zuerst.`,"Active.data":"Die `data` des Elements, von dem der Drag ausging.","Active.label":"Das `label` des Elements, an dem der Drag gestartet ist, der lesbare Name.","Active.type":"Der normalisierte `type` des Elements, von dem der Drag ausging; leer bedeutet, dass es zu jedem Drop-Ziel passt.","Active.element":`Element, bei dem der Drag begonnen hat. Es kann vom DOM getrennt werden (virtuelle Listen, Verschieben zwischen Listen).`,"Active.rect":"Layout-Rechteck von `element` beim Start des Drags.","Active.sensor":"Wie sich der Drag bewegt: `'pointer'` folgt Punkten, `'keyboard'` springt von Element zu Element (`SensorActivation.type`).","Active.external":"Ein Drag von außerhalb der Seite (Dateien, ein Link, Text oder Elemente aus einem anderen Fenster der App): was er trägt. Seine `items` werden für ihn erstellt (`element` ist ein Platzhalter).","Active.native":"Der eigene Drag des Browsers (`native` oder einer von außerhalb): Der Browser zeichnet das gezogene Bild, und es gibt kein Overlay.",Over:`Das Drop-Ziel unter dem Drag.`,"Over.id":`ID des Drop-Ziels.`,"Over.data":"Die Option `data` des Ziels.","Over.label":"Das `label` des Ziels, der lesbare Name.","Over.element":`Das Element des Ziels.`,"Over.rect":"Das Rechteck von `element`, während des Drags gemessen.","Over.accepted":"Ob die `accept`-Regel des Ziels die gezogenen Elemente annimmt.",DropDestination:"Wohin ein Drop die gezogenen Elemente legen würde: ein Platz in einer sortierbaren Liste oder einem Baum, so wie es das `to` des Drop-Events sagen wird (die Prop `to` des Overlays, live).","DropDestination.list":`ID der Liste oder des Baums.`,"DropDestination.index":"Index, den die gezogenen Elemente einnehmen: in der Liste oder, in einem Baum, unter den Geschwistern unter `parentKey`.","DropDestination.parentKey":"Bäume: der Knoten, unter den sie kommen; `null` auf der Wurzelebene.","DropDestination.depth":`Bäume: die Tiefe, in die sie kommen (Wurzeln sind 0).`,DragSource:`Woher die gezogenen Elemente kommen, wenn das eine sortierbare Liste ist.`,"DragSource.list":`Sortierbare Liste, aus der die gezogenen Elemente kommen.`,"DragSource.remove":`Entfernt die gezogenen Elemente aus ihrer Liste (Papierkorb-Zonen).`,DragMode:"Was ein Drop bewirkt: `'move'`, `'copy'` (die Elemente bleiben, Kopien von ihnen werden eingefügt), `'swap'` (`behavior: 'swap'`: zwei Elemente tauschen die Plätze) oder `'insert'` (ein einfaches ziehbares Element kommt als das Element in eine Liste, das sein `createItem` erzeugt hat).",DnDEvent:`Was Drag-Events mitführen: Monitore, die Events des Providers und die Hooks von Drop-Zielen erhalten es.`,"DnDEvent.active":`Der Drag.`,"DnDEvent.over":"Das Drop-Ziel unter dem Drag; `null` über nichts.","DnDEvent.pointer":`Zeiger in Viewport-Koordinaten, nach den Modifiern.`,"DnDEvent.delta":`Versatz seit dem Start des Drags, nach den Modifiern.`,"DnDEvent.position":"Wo die linke obere Ecke der gezogenen Box in `over` liegt, gemessen von dessen Padding-Kante und mit dessen Scrollposition: das `left`/`top`, das ein absolut positioniertes Element dorthin setzt, wo es abgelegt wurde (eine Notiz auf einem Board). `null` über nichts. Bezieht sich auf die Overlay-Box oder, mit `overlay: false`, auf das Element selbst.","DnDEvent.mode":"Was ein Drop tun würde: `'move'`, `'copy'` (`pull: 'clone'` einer Liste oder die Kopier-Taste, gehalten über Elementen, deren Liste `clone` kann), `'swap'` oder `'insert'`. Ein einfaches Drop-Ziel liest es, um zu kopieren statt zu verschieben.","DnDEvent.source":`Vorhanden, wenn die gezogenen Elemente aus einer sortierbaren Liste kommen.`,"DnDEvent.external":"Ein Drag von außerhalb der Seite: was er trägt (`active.external`). Seine Daten kommen beim Drop.",DnDEndEvent:"Was `onDragEnd` (und das `onDrop` des Ziels) erhält: das Event des Drops und wie er ausgegangen ist.","DnDEndEvent.dropped":`False, wenn der Drag außerhalb aller Drop-Ziele geendet hat.`,"DnDEndEvent.accepted":"Von `onBeforeDrop` angenommene IDs (alle gezogenen IDs, sofern keine Teilmenge zurückgegeben wurde).","DnDEndEvent.rejected":"Die anderen gezogenen IDs: `onBeforeDrop` hat sie ausgelassen, und sie fliegen zurück. Leer, wenn es alle angenommen hat.","DnDEndEvent.droppedOutside":"Ein Drag aus der Seite hinaus (`native`), der woanders abgelegt wurde: was dieser Ort damit gemacht hat. `'move'` nimmt die Elemente hier aus ihrer sortierbaren Liste; `'copy'` und `'link'` lassen sie dort.",BeforeDropResult:"Was `onBeforeDrop` entscheidet:\n- `'accept'` (oder `true` oder nichts): Der Drop wird ausgeführt;\n- `'reject'` (oder `false`): kein Drop, die Elemente fliegen zurück;\n- eine Liste von IDs: Nur diese Elemente werden angenommen, die anderen fliegen zurück;\n- `'continue'`: kein Drop, und der Drag geht weiter. Mit einem Zeiger folgt das Element ihm wieder (ohne gedrückte Taste), und das nächste Loslassen – also ein Klick – legt es ab; ein Touch nimmt es wieder auf; die Tastatur bewegt es wie zuvor. Escape bricht den Drag ab. Der Drop fragt `onBeforeDrop` erneut.",AcceptContext:"Womit eine `accept`-Regel in Form einer Funktion aufgerufen wird.","AcceptContext.active":`Der Drag.`,"AcceptContext.items":`Jedes gezogene Element.`,"AcceptContext.types":`Die Typen aller gezogenen Elemente, zusammen.`,AcceptRule:"`'*'` oder weggelassen nimmt alles an. Elemente ohne Typ passen zu jeder String-Regel (entspricht `groups: []` aus v2).",AcceptMode:"`'all'`: Jedes gezogene Element muss passen; `'some'`: mindestens eines (die übrigen können in `onBeforeDrop` abgelehnt werden).",KeyboardMoveContext:"Womit `getKeyboardCoordinates` für eine Pfeiltaste aufgerufen wird.","KeyboardMoveContext.active":`Der Drag.`,"KeyboardMoveContext.pointer":`Wo der Drag gerade ist, in Viewport-Koordinaten.`,"KeyboardMoveContext.direction":`Einheitsvektor der gedrückten Pfeiltaste.`,DnDMonitor:"Hooks für jeden Drag unter dem Provider (`useDnDMonitor`).","DnDMonitor.onDragStart":`Ein Drag hat begonnen, nach seiner Aktivierung.`,"DnDMonitor.onDragMove":`Der Drag hat sich bewegt (höchstens einmal pro Frame).`,"DnDMonitor.onDragOver":`Das Ziel unter dem Drag hat sich geändert.`,"DnDMonitor.onBeforeDrop":"Läuft, bevor der Drop festgeschrieben wird (siehe `BeforeDropResult`): `'reject'` lehnt ihn ab, IDs nehmen eine Teilmenge an.","DnDMonitor.onDragEnd":"Eine Benachrichtigung, sobald der Drop erledigt ist: Sortierbare Listen haben ihr `onDrop` ausgeführt und ihn geschrieben.","DnDMonitor.onDragCancel":`Der Drag wurde abgebrochen oder sein Drop abgelehnt: Die Elemente fliegen zurück.`,"DnDMonitor.onDragResume":"`onBeforeDrop` hat `'continue'` geantwortet: Es gab keinen Drop, und der Drag geht weiter.","DnDMonitor.onDragSettle":"Das Overlay eines beendeten Drags ist gelandet: nach seiner Drop-Animation (oder dem Rückflug bei einem Abbruch), mit dem Event, das `onDragEnd` (ein `DnDEndEvent`) oder `onDragCancel` bekommen hat. Der nächste Drag kann inzwischen begonnen haben: Drags warten nicht auf Landungen.","DnDMonitor.getKeyboardCoordinates":`Drags per Tastatur: nächste Zeigerposition für eine Pfeiltaste (z. B. der nächste sortierbare Slot).`,DnDSelection:`Die ausgewählten ziehbaren Elemente, nach ID: Ein Drag eines von ihnen trägt sie alle (Multi-Drag). Da sie nach ID geführt wird, übersteht eine Auswahl Unmounts (virtuelle Listen).`,"DnDSelection.ids":`Die ausgewählten IDs, reaktiv.`,"DnDSelection.has":"Ob `id` ausgewählt ist.","DnDSelection.add":`Wählt diese IDs aus.`,"DnDSelection.delete":`Hebt die Auswahl dieser IDs auf.`,"DnDSelection.toggle":"Wählt `id` aus oder hebt die Auswahl auf; `force: true` wählt es aus, `false` hebt die Auswahl auf.","DnDSelection.set":`Wählt diese IDs aus und keine anderen.`,"DnDSelection.clear":`Hebt die Auswahl aller IDs auf.`,DnDState:"Der Zustand des Drags endet, wenn über den Drop entschieden ist: `active`, `over` und `pointer` sind `null` (und Drop-Zonen nehmen nichts mehr an), während das Overlay noch an seinen Platz animiert. Abgeleitete UI mischt nie den alten Drag mit den neuen Daten. Während ein asynchrones `onBeforeDrop` entscheidet, bleibt der Zustand so, wie er beim Loslassen war, aber die Seite ist nicht mehr im Drag-Modus: Ihr eigener Cursor und die Textauswahl sind zurück (ein Bestätigungsdialog funktioniert normal), und das Overlay wartet dort, wo es abgelegt wurde.\n\n`status` ist `'dragging'`, solange ein Drag läuft, sonst `'dropping'`, solange über einen Drop entschieden wird oder ein Overlay noch landet, sonst `'idle'` (abgesehen von `'activating'` und `'selecting'`). Ein neuer Drag wartet nicht auf die Landungen: Er startet sofort, und sie enden um ihn herum.","DnDState.status":"Was der Provider gerade tut (siehe `DnDStatus`).","DnDState.active":"Der laufende Drag; `null` ohne Drag und sobald über seinen Drop entschieden ist.","DnDState.over":"Das Drop-Ziel unter dem Drag; `null` über nichts.","DnDState.pointer":"Zeiger in Viewport-Koordinaten, nach den Modifiern; `null` ohne Drag.","DnDState.position":"Wo die linke obere Ecke der gezogenen Box gerade in `over` liegt, live: `DnDEvent.position` bei jeder Bewegung. `null` über nichts. Eine Overlay-Komponente liest es, um zu zeigen, wo sie landen würde (eine Uhrzeit in einem Kalender).","DnDState.activation":"`progress`: wie weit ein Drücken seiner Aktivierungsbedingung nähergekommen ist, von 0 bis 1, solange `status` `'activating'` ist: z. B. ein Ring, der sich während eines langen Drückens füllt.","DnDState.isAutoScrolling":`Auto-Scroll bewegt gerade einen Container.`,"DnDState.selection":"Die ausgewählten ziehbaren Elemente (siehe `DnDSelection`).","DnDState.cancel":`Bricht den Drag (er fliegt zurück) oder die ausstehende Aktivierung ab.`,"DnDState.addWindow":"Drags funktionieren auch in `view`: einem anderen Fenster der App, das einen Teil von ihr zeigt (ein mit `window.open` geöffnetes Popup, ein abgelöstes Panel, ein Document-Picture-in-Picture-Fenster). Eine Komponente, die beim Mounten hineingerendert wird, wird von selbst gefunden; Inhalt, den ein Teleport später dorthin verschiebt, nicht, also nenne das Fenster, wenn du es öffnest. Bis es sich schließt oder die zurückgegebene Funktion läuft, hört der Provider darauf, injiziert dort seine Styles, und Drags, die darin starten, bleiben darin (sein Viewport, seine Ziele, das Overlay in seinem `<body>`). Elemente mit `native` wechseln außerdem zwischen den Fenstern.",DraggableOptions:"Optionen von `makeDraggable`. Jede Option außer `canDrag` nimmt einen Wert, ein Ref oder einen Getter entgegen (`overlay`, `dropAnimation`: einen Wert oder ein Ref) und wird gelesen, wenn sie gebraucht wird, sodass eine Änderung spätestens ab dem nächsten Drag gilt.","DraggableOptions.id":"Stabile ID. Übergib in virtuellen Listen, in denen Elemente wiederverwendet werden, einen Getter. Standard: `useId()`, stabil zwischen Server- und Client-Rendering, aber neu für jede Komponenteninstanz.","DraggableOptions.data":"Alles, was der Drag mitführen soll: Events und Drop-Ziele lesen es als `active.data`.","DraggableOptions.label":"Der lesbare Name: Screenreader-Texte nennen ihn statt der ID (`Picked up Tomato`). Events tragen ihn als `active.label` und in `items`.","DraggableOptions.type":"Sein Typ oder seine Typen, abgeglichen mit den `accept`-Regeln der Drop-Ziele. Ohne Typ passt es zu jedem Ziel.","DraggableOptions.disabled":"`true`: Es kann nicht gezogen werden (es meldet `aria-disabled`).","DraggableOptions.handle":`Element oder Selektor innerhalb des ziehbaren Elements, der den Drag startet (und die Attribute bekommt).`,"DraggableOptions.activation":"Überschreibt `activation` des Providers. Wird gelesen, wenn ein Druck beginnt.","DraggableOptions.canDrag":`Zusätzliche Bedingung, z. B. nur ziehen, solange eine Taste gedrückt ist.`,"DraggableOptions.overlay":"`true` (Standard): Ein Overlay folgt dem Zeiger, gerendert vom Slot `#overlay` des Providers oder als Klon des Elements. Eine Komponente: Das Overlay rendert sie mit `OverlayProps`, vor dem Slot. `false`: kein Overlay, das Element selbst bewegt sich über das zurückgegebene `transform`. Ein Wert oder ein Ref (eine Funktion ist eine funktionale Komponente, `(props) => <Card {...props} />` funktioniert also). Ob es ein Overlay gibt, wird beim Start des Drags entschieden; ein mitten im Drag umgeschaltetes Ref tauscht die Komponente sofort (siehe `overlayTransition` des Providers). Das `overOverlay` eines Drop-Ziels gewinnt, solange der Drag darüber ist. Der Klon lässt die Druckeffekte von UI-Kits (Ripples) weg sowie jedes Element darin, das mit `data-dnd-no-clone` markiert ist.","DraggableOptions.dropAnimation":"Wie das Overlay landet, wenn ein Drag dieses Elements endet, statt der `dropAnimation` des Providers; die `overDropAnimation` eines Drop-Ziels gewinnt. Ein Wert oder ein Ref (eine Funktion ist die Animation), gelesen beim Drop.","DraggableOptions.modifiers":"Modifier für Drags, die hier beginnen, angewendet nach den `modifiers` des Providers: z. B. `[restrictToVerticalAxis]` für ein Element auf einer Seite, auf der sich andere Drags frei bewegen. Wird beim Start des Drags gelesen.","DraggableOptions.axis":"Beschränkt Drags, die hier beginnen, auf eine Achse: `'x'` bewegt nur horizontal, `'y'` nur vertikal. Die Sperre kommt nach `modifiers` (`restrictToHorizontalAxis` / `restrictToVerticalAxis` als Letztes), sie gilt also, egal was diese tun. Wird beim Start des Drags gelesen.","DraggableOptions.keyboardMode":`Pfeiltasten bei freien Drags: um Pixel bewegen (Standard) oder zwischen annehmenden Drop-Zielen springen. Wird bei jedem Druck auf eine Pfeiltaste gelesen.`,"DraggableOptions.attributes":"Setzt role-/tabindex-/aria-*-Attribute (Standard `true`) und überschreibt nie deine eigenen. Die ID der Anweisungen des Providers wird einem vorhandenen `aria-describedby` als weiteres Token hinzugefügt (ein Tooltip eines UI-Kits auf demselben Element behält sein eigenes), und nur dieses Token wird je entfernt. Live: Ausschalten entfernt, was die Bibliothek gesetzt hat.","DraggableOptions.native":"Ein Maus-Drag des Elements ist der eigene Drag des Browsers, der die Seite verlassen kann: auf den Desktop, in eine andere App oder einen anderen Tab, in ein anderes Fenster der App. Auf der Seite funktioniert er wie gewohnt (Ziele, Listen, die Platz machen), aber der Browser zeichnet das gezogene Bild statt des Overlays. Drags per Touch und Tastatur bleiben die der Bibliothek. `true` trägt das `label` als Text. Wird gelesen, wenn ein Druck beginnt. `canDrag` wird beim Drücken gefragt; wie weit sich eine Maus bewegen muss, bevor ihr Drag startet, entscheidet der Browser (`activation` gilt dafür nicht).",DraggableReturn:"Was `makeDraggable` zurückgibt.","DraggableReturn.id":"Die ID des ziehbaren Elements: die Option `id` oder die dafür erzeugte.","DraggableReturn.isDragging":`Es wird gezogen (auch als weiteres Element eines Multi-Drags), oder sein Overlay landet noch.`,"DraggableReturn.transform":"Versatz, der bei `overlay: false` anzuwenden ist: der des Drags, abzüglich dessen, wie weit sich der Inhalt, in dem das Element liegt, seit dem Start bewegt hat (die Seite oder ein Container wurde gescrollt), sodass das Element unter dem Zeiger bleibt.","DraggableReturn.selected":`Es ist in der Auswahl des Providers: Ein Drag eines ausgewählten Elements trägt sie alle. Setze den Wert, um es aus- oder abzuwählen.`,Placement:"In welchen Hälften eines überfahrenen Drop-Ziels der Zeiger ist (`DroppableReturn.placement`).","Placement.top":`In seiner oberen Hälfte.`,"Placement.right":`In seiner rechten Hälfte.`,"Placement.bottom":`In seiner unteren Hälfte.`,"Placement.left":`In seiner linken Hälfte.`,DroppableOptions:"Optionen von `makeDroppable`.\n\n**Drop in ein Element.** Ein Drop-Ziel auf dem DOM-Element eines sortierbaren Elements (oder darin) funktioniert wie überall sonst, mit einer Regel, solange die Liste dieses Elements den Drag sortieren würde: Es zählt nur, solange der Zeiger in der Mitte des Elements ist (25–75 % entlang der Achse der Liste; x in Rastern), wo der Drop in das Ziel geht und die Liste sich dafür nicht bewegt. Nahe den Rändern des Elements sortiert die Liste wie gewohnt. Ein Ziel, dessen `accept` den Drag ablehnt, wird ausgelassen, sodass die Liste über dem Element sortiert wie über jedem anderen (es muss nicht deaktiviert werden). Die Tastatur hält auf einem solchen Ziel an, bevor sie an seinem Element vorbeigeht. Ein Drag zielt nie auf das, was er trägt: kein Ziel in (oder auf) einem gezogenen Element und keins in dem Slot, in dem eines landet. Um die Elemente in `onDrop` aus ihrer Liste zu nehmen, rufe `e.source.remove()` auf.\n\nJede Option außer den Callbacks nimmt einen Wert, ein Ref oder einen Getter entgegen (`accept`, `overOverlay`, `overDropAnimation`: einen Wert oder ein Ref) und wird live gelesen, während ein Drag sein Ziel sucht.","DroppableOptions.id":"Standard: `useId()`, stabil zwischen Server- und Client-Rendering.","DroppableOptions.data":"Alles, was es über das Ziel zu sagen gibt: Events tragen es als `over.data`.","DroppableOptions.label":"Der lesbare Name: Screenreader-Texte nennen ihn statt der ID (`over Trash`); Events tragen ihn als `over.label`.","DroppableOptions.accept":`Was dieses Ziel annimmt. Innerhalb eines sortierbaren Elements lässt ein Ziel, das den Drag ablehnt, die Liste darüber sortieren. Ein Wert oder ein Ref: Eine Funktion ist eine Regel.`,"DroppableOptions.acceptMode":"Standard `'all'`.","DroppableOptions.disabled":"`true`: Drags gehen darüber hinweg, als wäre es nicht da.","DroppableOptions.priority":`Bei Zielen, die sich ohne Verschachtelung überlappen, gewinnt der höhere Wert (Standard 0). Sortierbare Elemente schlagen Container.`,"DroppableOptions.overOverlay":"Was das Overlay zeigt, während ein Drag, den dieses Ziel annimmt, darüber ist: eine Komponente, die `OverlayProps` bekommt und statt des eigenen Overlays des Drags gerendert wird (der Komponente des gezogenen Elements, des Slots des Providers oder des Klons); dieses bekommt sie als Standard-Slot, um es einzuhüllen oder wegzulassen (`<slot />`). Sie bleibt, während der Drop hier landet. Drags ohne Overlay (`overlay: false`) bleiben ohne. Ein Wert oder ein Ref, live gelesen; der Wechsel der Komponente wird mit der `overlayTransition` des Providers animiert. (Bei ziehbaren Elementen, Elementen und Listen ist `overlay` das eigene Overlay des Drags; sortierbare Listen und Bäume nehmen diese Option ebenfalls als `overOverlay` entgegen.)","DroppableOptions.overDropAnimation":"Wie das Overlay landet, wenn es hier abgelegt wird, statt der `dropAnimation` des gezogenen Elements und des Providers: `false` lässt es dort, wo es abgelegt wurde (die eigene Animation einer Overlay-Komponente, ein Spritzer, läuft dort ab), eine Funktion animiert es. Ein Wert oder ein Ref, gelesen beim Drop.","DroppableOptions.onDragEnter":"Ein Drag ist über dieses Ziel gekommen, ob es den Drag annimmt oder nicht (`event.over.accepted`).","DroppableOptions.onDragLeave":`Der Drag hat dieses Ziel verlassen.`,"DroppableOptions.onBeforeDrop":"Wird gefragt, bevor ein Drop auf dieses Ziel durchgeht, nach dem `onBeforeDrop` der Monitore, wenn es den Drag annimmt (siehe `BeforeDropResult`). Darf asynchron sein: Das Overlay wartet dort, wo es abgelegt wurde. Ein Fehler lehnt den Drop ab.","DroppableOptions.onDrop":"Ein Drop auf dieses Ziel ist durchgegangen: Tu, was er bedeutet (das Element verschieben, die Datei hochladen). Wenn ein `onBeforeDrop` nur einige der gezogenen Elemente angenommen hat, enthält `event.accepted` ihre IDs und `event.rejected` die anderen, die zurückfliegen; `active` ist weiterhin der ganze Drag.","DroppableOptions.external":"Nimmt Drags von außerhalb der Seite an: Dateien vom Desktop, einen Link oder Text aus einer anderen App oder einem anderen Tab (das Drag and Drop des Browsers). Sie funktionieren wie die Drags der Bibliothek (`isOver`, `isAccepting`, die Events), und `e.external` hat beim Drop ihre Daten. Ziele ohne `external` ignorieren sie. Ein Wert, ein Ref oder ein Getter, live gelesen.",DroppableReturn:"Was `makeDroppable` zurückgibt.","DroppableReturn.id":"Die ID des Ziels: die Option `id` oder die dafür erzeugte.","DroppableReturn.isOver":"Ein Drag ist darüber (mit `external` auch einer von außerhalb der Seite).","DroppableReturn.isAccepting":`Etwas wird gezogen, und dieses Ziel nimmt es an.`,"DroppableReturn.placement":`Position des Zeigers relativ zu den Hälften des Ziels, während der Zeiger darüber ist.`,DnDProvider:"Verwaltet die Drags von allem, was darin gerendert wird: Eingabe, Overlay, Auswahl, Auto-Scroll und die Screenreader-Ansagen (siehe `DnDProviderProps`).",DragPreview:"Der Standardklon eines gezogenen Elements (siehe `DragPreviewProps`). Eigene Overlays ordnen damit mehrere Elemente selbst an; das Standard-Overlay zeigt damit einen Multi-Drag.",makeDraggable:`Macht ein Element ziehbar. Standardmäßig freies Ziehen; sortierbare Listen bauen darauf auf.`,makeDroppable:`Macht ein Element zu einem Drop-Ziel.`,useDnD:`Schreibgeschützter Drag-Zustand für eigene UI (Hervorheben gültiger Ziele, Spinner, Fortschritt).`,useDnDMonitor:`Abonniert die Events jedes Drags unter dem Provider, solange die aufrufende Komponente (oder der Effect Scope) lebt.`,useDnDContext:"Der Provider über dieser Komponente, als opakes Handle für `provideDnDContext`: Es bringt den Provider in Shadow Roots und separate Vue-Apps.",provideDnDContext:"Teilt einen Provider (aus `useDnDContext()`) mit einer anderen Vue-App, z. B. einer, die in einem Shadow Root gemountet ist.",makeSortableList:"Macht einen Container zu einer sortierbaren Liste. Rendere die zurückgegebenen `items` (die Entwurfsreihenfolge), nicht dein Array: Der Drop wird nach `onDrop` in `options.items` zurückgeschrieben, sofern `event.preventDefault()` `event.result` nicht dir überlässt.",makeSortableItem:"Macht ein Element zu einer Zeile einer sortierbaren Liste oder eines Baums: Sie wird gezogen, macht Platz und landet in ihrem Slot. Rufe es in einer Komponente auf, die innerhalb derjenigen gerendert wird, die `makeSortableList` (oder `makeSortableTree`) aufgerufen hat; von mehreren dort erstellten Listen gehört die Zeile zur innersten, deren DOM-Element sie enthält. Identifiziere die Zeile mit `item` (Schlüssel aus `getKey` der Liste, standardmäßig `item.id`) oder `id`.",makeSortableTree:"Macht einen Container zu einem sortierbaren Baum. Rendere die zurückgegebenen `items` (sichtbare Knoten in Entwurfsreihenfolge, eingerückt nach `depth`) mit einer Zeilenkomponente, die `makeSortableItem` aufruft. Beim Drop werden nach `onDrop` die verschobenen Knoten (mit ihren Teilbäumen) in `options.items` geschrieben, sofern `event.preventDefault()` `event.result` nicht dir überlässt.",makeSelectionArea:'Macht ein Element zu einem Auswahlbereich mit Auswahlrahmen für die ziehbaren Elemente darin. Rendere das Rechteck selbst: `<div v-if="isSelecting" class="band" :style="style" />`.',makeDragArea:"Macht ein Element zu einem Drag-Bereich: Die Drags, die darin beginnen (ziehbare und sortierbare Elemente), folgen seinen Regeln, siehe `DragAreaOptions`. Ein Provider kann dann die ganze App bedienen, mit Boards, Canvases und Feeds, die jeweils auf ihre eigene Art ziehen. Bei verschachtelten Bereichen gewinnt der nächstgelegene.",defineSensor:"Definiert einen Sensor (siehe `Sensor`): Es hilft nur bei den Typen und gibt sein Argument zurück.",useSensor:"Führt einen Sensor im darüberliegenden Provider aus, solange die aufrufende Komponente (oder der Effect Scope) lebt, neben den `sensors` des Providers. Sein Drag wird beim Unmounten abgebrochen.",pointerSensor:"Maus, Touch und Stift über Pointer Events. Standardmäßig in `sensors`.",keyboardSensor:"Leertaste/Enter, Pfeiltasten und Escape (neu belegbar mit der Option `keyboard` des Providers). Standardmäßig in `sensors`; er bricht mit Escape auch Zeiger- und eigene Drags ab, selbst mit `keyboard: false`.",pointerFirst:`Standard: was unter dem Zeiger ist, sonst was das Overlay überlappt.`,pointerWithin:`Ziele unter dem Zeiger, aus dem Hit-Testing: berücksichtigt z-Reihenfolge, Overlays und Shadow Roots.`,rectIntersection:`Ziele, die das Overlay überlappen: höhere Priorität, dann tiefere Verschachtelung, dann Intersection over Union.`,closestCenter:`Jedes Ziel, nach dem Abstand zwischen den Mittelpunkten.`,closestCorners:`Jedes Ziel, nach der Summe der Abstände zwischen den Ecken (gut für gestapelte Ziele wie Kanban-Spalten).`,restrictToVerticalAxis:"Bewegt nur vertikal: Horizontal bleibt es bei dem Inhalt, in dem es begann (`containerShift`), wie auch immer die Seite scrollt. Die Option `axis: 'y'` macht dasselbe, als Letztes.",restrictToHorizontalAxis:"Bewegt nur horizontal: Vertikal bleibt es bei dem Inhalt, in dem es begann (`containerShift`), wie auch immer die Seite scrollt. Die Option `axis: 'x'` macht dasselbe, als Letztes.",restrictToWindowEdges:`Hält das Overlay innerhalb des Fensters.`,restrictToParent:`Hält das Overlay innerhalb des Containers, in dem der Drag begann: der sortierbaren Liste (nicht ihres DOM-Elternelements) oder, bei einfachen ziehbaren Elementen, des Elternelements.`,restrictToElement:`Hält das Overlay innerhalb eines Elements: das Element, ein Ref oder ein Getter.`,restrictToFirstScrollableAncestor:`Hält das Overlay innerhalb des ersten scrollbaren Vorfahren des gezogenen Elements.`,snapToGrid:"Lässt das Overlay an einem Raster einrasten, in der nächsten Zelle: Eine Zahl ist die Größe quadratischer Zellen; Optionen legen jede Achse fest, wo das Raster beginnt und ein Gleiten zwischen den Zellen (`SnapToGridOptions`).",snapCenterToCursor:`Zentriert das Overlay unter dem Zeiger, statt den Greifversatz beizubehalten.`,ExternalFile:"Eine Datei eines Drags von außerhalb, so wie `ExternalAccept.files` nach ihr gefragt wird. Solange die Dateien über der Seite gehalten werden, nennt der Browser nur ihre Typen: `name` und `size` kommen beim Drop.","ExternalFile.type":"Ihr MIME-Typ (`image/png`); `''`, wenn der Browser ihn nicht nennen kann.","ExternalFile.name":"Sein Name mit der Endung (`notes.md`), beim Drop.","ExternalFile.size":`Seine Größe in Bytes, beim Drop.`,ExternalAccept:"Was ein Drop-Ziel, eine Liste oder ein Baum von Drags annimmt, die von außerhalb der Seite kommen: Dateien vom Desktop, einen Link oder Text aus einer anderen App oder einem anderen Tab (`external`).","ExternalAccept.files":"Dateien: `true` nimmt jede an. Oder wie bei `<input accept>`: MIME-Typen (`image/*`, `application/pdf`) und Dateiendungen (`.md`), als String mit Kommas oder als Liste; Dateiendungen werden beim Drop geprüft. Oder eine Funktion, die zu jeder Datei gefragt wird (`false` lehnt sie ab). Ordner werden nie angenommen.","ExternalAccept.multiple":"Mehrere Dateien auf einmal (Standard `true`); `false` lehnt einen Drag mit mehr als einer Datei ab.","ExternalAccept.links":"Links (`text/uri-list`): eine Adresse, die aus einem anderen Tab gezogen wird, ein Link aus einer Seite.","ExternalAccept.text":"Reiner Text (`text/plain`): eine Auswahl, die aus einer anderen App gezogen wird.","ExternalAccept.types":`Andere MIME-Typen, die es annimmt, genau so, wie andere Apps sie anbieten.`,ExternalData:"Ein Drag von außerhalb der Seite (`Active.external`, `DnDEvent.external`). Solange er gehalten wird, sagt der Browser, was er trägt, nicht die Daten: Die Dateien, Links und der Text kommen beim Drop (`ready`).","ExternalData.types":"Die MIME-Typen, die er anbietet (`Files`, `text/uri-list`, `text/plain`, eigene einer App).","ExternalData.fileTypes":"Die MIME-Typen seiner Dateien, einer pro Datei (`''`, wenn der Browser ihn nicht nennen kann).","ExternalData.files":`Beim Drop: die Dateien, die das Ziel annimmt (ohne Ordner und abgelehnte Dateien).`,"ExternalData.urls":"Beim Drop: seine Links (`text/uri-list`).","ExternalData.text":`Beim Drop: sein reiner Text.`,"ExternalData.html":`Beim Drop: sein HTML.`,"ExternalData.getData":"Beim Drop: die Daten jedes Typs, den er anbietet (`''` vorher und für einen Typ, den er nicht anbietet).","ExternalData.ready":`Er wurde abgelegt: Die Daten oben sind da.`,"ExternalData.group":"Elemente der Bibliothek, die aus einem anderen Fenster der App hereingezogen werden (`native`): der Name ihrer sortierbaren Gruppe. Die Listen dieser Gruppe nehmen sie an, als kämen sie aus einer ihrer eigenen Listen; `active.items` enthält sie.",NativeDragOptions:"Ein ziehbares oder sortierbares Element, das eine Maus aus der Seite hinausziehen kann (`native`): auf den Desktop, in eine andere App, einen anderen Tab, ein anderes Fenster der App.","NativeDragOptions.data":"Was andere Apps und Seiten bekommen: Text nach MIME-Typ, als `{ 'text/plain': title, 'text/uri-list': url }`. Wird beim Start des Drags gelesen. Sortierbare Elemente tragen außerdem sich selbst, für die Listen ihrer Gruppe in einem anderen Fenster der App.","NativeDragOptions.effect":"Was der Drag dem Ort, an dem er abgelegt wird, erlaubt (`effectAllowed`). Standard `'copyMove'`: Ein Verschieben nimmt die Elemente hier aus ihrer Liste, eine Kopie lässt sie dort.",Key:`Eine ID oder ein Schlüssel: eines ziehbaren Elements, eines Drop-Ziels, einer Liste, eines Elements einer Liste.`,MaybeReadonlyRefOrGetter:"Ein Wert, ein Getter oder ein beliebiges Ref (beschreibbar, shallow, computed, readonly – z. B. aus `useTemplateRef`), das die Bibliothek nur liest. Anders als Vues `MaybeRefOrGetter` akzeptiert er `Ref<string>`, wo `string | number` erwartet wird.",MaybeReadonlyRef:"Ein Wert oder ein beliebiges Ref, für Optionen, bei denen eine Funktion ein eigenständiger Wert ist (eine Overlay-Komponente, eine Annahmeregel, eine eigene Animation), sodass ein Getter nicht davon zu unterscheiden wäre. Halte Komponenten in einem `shallowRef` (oder einem computed): Vue darf sie nicht reaktiv machen.",MaybeElement:"Ein Element: ein HTML- oder SVG-Element oder eine Komponenteninstanz (ihr Wurzelelement, `$el`), so wie ein Template-Ref sie liefert. `null` oder `undefined`, solange es keins gibt (noch nicht gemountet).",MaybeElementRef:"Das Element, mit dem ein Composable arbeitet (`makeDraggable(target)`): das Element, ein Template-Ref (`useTemplateRef`) oder ein Getter. Es darf sich ändern (ein `v-if`): Die Bibliothek folgt ihm.",Coordinates:"Ein Punkt oder ein Versatz, in px: eine Position ab der oberen linken Ecke des Viewports oder ein Versatz von dort, wo der Drag begann (`delta`, `transform`).","Coordinates.x":`Horizontal, nach rechts wachsend.`,"Coordinates.y":`Vertikal, nach unten wachsend.`,Size:`Eine Breite und eine Höhe, in px.`,"Size.width":`Breite in px.`,"Size.height":`Höhe in px.`,Rect:"Eine Box in px, in Viewport-Koordinaten, wie `getBoundingClientRect()` sie liefert.","Rect.top":`Seine Oberkante, vom oberen Rand des Viewports aus.`,"Rect.left":`Seine linke Kante, vom linken Rand des Viewports aus.`,"Rect.width":`Seine Breite.`,"Rect.height":`Seine Höhe.`,"Rect.right":"Seine rechte Kante, vom linken Rand des Viewports aus: `left + width`.","Rect.bottom":"Seine Unterkante, vom oberen Rand des Viewports aus: `top + height`.",MaybePromise:"Ein Wert oder ein Promise davon: was ein Hook zurückgibt, der asynchron sein darf (`onBeforeDrop`).",DnDStatus:"Was der Provider gerade tut:\n- `'idle'`: nichts;\n- `'activating'`: Ein Drücken wartet auf seine Aktivierungsbedingung (eine Distanz, ein langes Drücken);\n- `'dragging'`: Ein Drag läuft;\n- `'dropping'`: Über einen Drop wird entschieden (ein asynchrones `onBeforeDrop`), oder ein Overlay landet noch;\n- `'selecting'`: Ein Auswahlbereich zeichnet seinen Rahmen.",SensorType:"Wie sich ein Drag bewegt, egal welcher Sensor ihn steuert (`SensorActivation.type`): `'pointer'` folgt Punkten, `'keyboard'` bewegt sich von Element zu Element.",PointerKind:"Die Art des Zeigers, der gedrückt hat (`PointerEvent.pointerType`): Die Aktivierung wird pro Art eingestellt.",ActivationConstraint:"Was ein Drücken tun muss, bevor es zum Drag wird: `distance` zurücklegen oder für `delay` gehalten werden, je nachdem, was zuerst eintritt. Nichts gesetzt: Der Drag startet sofort.","ActivationConstraint.distance":`Pixel, die der Zeiger zurücklegen muss, bevor der Drag beginnt.`,"ActivationConstraint.delay":`Millisekunden, die der Zeiger gedrückt bleiben muss, bevor der Drag beginnt.`,"ActivationConstraint.tolerance":"Mit `delay`: Bewegung in px, die die Aktivierung abbricht, damit die Seite scrollen kann.",ActivationOptions:"Pro Zeigerart. Standardwerte: Maus `{ distance: 4 }` (sofort bei einem Handle), Stift `{ distance: 4 }`, Touch `{ delay: 200, tolerance: 5 }`.",AnnouncedPosition:"Ein Platz in einer sortierbaren Liste oder einem Baum (unter seinen sichtbaren Zeilen): `index` zählt ab 0, von `length`.","AnnouncedPosition.list":`ID der Liste oder des Baums.`,"AnnouncedPosition.label":"Das `label` der Liste, der lesbare Name.","AnnouncedPosition.index":"Der Platz, ab 0: Die eingebauten Texte sagen `index + 1`.","AnnouncedPosition.length":`Wie viele Plätze die Liste hat.`,AnnouncementContext:`Worum es in einer Ansage geht, über das Event hinaus: für eigene Texte (eine andere Sprache, andere Worte), die sagen, was die eingebauten sagen.`,"AnnouncementContext.position":`In einer sortierbaren Liste oder einem Baum: wo die gezogenen Elemente sind. Am Anfang, wo sie aufgenommen wurden; während der Bewegung, wo sie landen würden (keine außerhalb der Listen); am Ende, wo sie gelandet sind oder wohin sie zurückgekehrt sind.`,"AnnouncementContext.partner":`Ein Tausch: das Element, mit dem das gezogene getauscht wurde, und wo es jetzt ist.`,"AnnouncementContext.count":`Wie viele Elemente der Drag trägt.`,"AnnouncementContext.copy":"Der Drag kopiert (`group.pull: 'clone'`, die Kopier-Taste).",Announcements:"Texte für Screenreader, pro Event. Gib `undefined` für den eingebauten Text zurück, `''` für keinen. `context` enthält die Positionen, die die eingebauten Texte sortierbarer Listen sprechen.\n\nEin Text wird von der Live-Region des Providers gesprochen (Bewegungen, sobald der Drag 500 ms ruht); `undefined` überlässt das Event der nächsten Quelle (den Texten von Integrationen wie sortierbaren Positionen, dann den Standardtexten). Für das beim Aufnehmen gefundene Ziel wird keine Bewegung angesagt: Es hat sich noch nichts bewegt.","Announcements.onDragStart":`Ein Drag hat begonnen.`,"Announcements.onDragOver":`Der Drag ist über ein anderes Ziel oder an einen anderen Platz in einer Liste gelangt (sobald er 500 ms ruht).`,"Announcements.onDragEnd":`Der Drop ist durchgegangen, oder der Drag endete außerhalb aller Ziele.`,"Announcements.onDragCancel":`Der Drag wurde abgebrochen oder sein Drop abgelehnt.`,"Announcements.onDragResume":"`onBeforeDrop` hat `'continue'` geantwortet: Der Drag geht weiter.",Announcer:`Die Texte einer Integration (sortierbare Listen) und der Kontext, den sie für die eigenen Texte des Providers kennt.`,KeyboardOptions:"Ziehen per Tastatur (`keyboard` des Providers): die Tasten und die Schrittweite freier Drags.","KeyboardOptions.keys":"Die Tasten, die aufnehmen (`start`), ablegen und abbrechen, als `KeyboardEvent.code` (`'Space'`, `'KeyW'`) oder `.key` (`'Enter'`, `'w'`). Standard: Leertaste und Enter nehmen auf und legen ab, Escape bricht ab. Die Pfeiltasten bewegen immer.","KeyboardOptions.step":`Pixel pro Druck auf eine Pfeiltaste bei freien (nicht sortierbaren) Drags. Standard 25.`,AutoScrollOptions:"Wie Container scrollen, wenn sich ein Drag ihren Rändern nähert (`autoScroll` des Providers).","AutoScrollOptions.threshold":`Randzone als Bruchteil der Containergröße. Standard 0.2 (begrenzt auf 24–96px).`,"AutoScrollOptions.maxSpeed":`Höchstgeschwindigkeit in px pro Frame von 16ms.`,"AutoScrollOptions.acceleration":"Geschwindigkeit in px pro Frame, wenn der Zeiger am Rand des Containers ist: langsamer innerhalb der Randzone, schneller jenseits des Rands, bis zu `maxSpeed`. Standard 10.",HapticPattern:"Eine Vibration (`navigator.vibrate`): ihre Länge in ms oder ein Ein/Aus-Muster. `true` ist die Standardvibration (10ms; `[20, 40, 20]` für `refuse`), `false` oder `0` keine.",HapticsOptions:`Wann Drags per Touch vibrieren. Das tun nur Drags, die per Touch gestartet wurden; wo der Browser nicht vibrieren kann (iOS Safari) oder es blockiert (noch kein Tippen auf der Seite), passiert nichts.`,"HapticsOptions.start":"Der Drag beginnt, nach dem langen Drücken. Standard `true`.","HapticsOptions.enter":"Der Drag betritt ein Drop-Ziel (eine Liste, eine Drop-Zone), das ihn annimmt. Standard `false`.","HapticsOptions.drop":"Der Drop wird ausgeführt. Standard `false`.","HapticsOptions.refuse":"Der Drop wird abgelehnt (von einem Ziel oder von `onBeforeDrop`), und die Elemente fliegen zurück. Standard `false`.",DnDProviderProps:"Props von `DnDProvider`. Die meisten werden gelesen, wenn der Provider sie braucht: Ändere eine, und der nächste Drag verwendet sie.","DnDProviderProps.collision":"Wie das Ziel unter dem Drag gewählt wird. Standard `pointerFirst`; eine andere eingebaute (`closestCorners`) oder deine eigene.","DnDProviderProps.modifiers":`Modifier für jeden Drag, zuerst angewendet: Die von Drag-Bereichen, ziehbaren Elementen und Listen kommen danach.`,"DnDProviderProps.animation":`Standard-FLIP-Animation für sortierbare Listen.`,"DnDProviderProps.dropAnimation":"Wie das Overlay beim Drop landet und beim Abbrechen zurückfliegt, wenn nichts Näheres eine setzt: Zuerst kommt die `overDropAnimation` des Drop-Ziels, dann die eigene des gezogenen Elements (oder die seiner Liste), dann diese.","DnDProviderProps.animateChanges":"Standardwert von `animateChanges` für sortierbare Listen und Bäume: Änderungen ihrer Elemente, die kein Drag ausgelöst hat. Standardmäßig aus.","DnDProviderProps.autoScroll":"Scrollt Container und die Seite, wenn sich ein Drag ihren Rändern nähert. Standard `true`; Optionen stimmen es ab, `false` schaltet es aus. Listen, Bäume und Drag-Bereiche können es überschreiben.","DnDProviderProps.activation":"Was ein Drücken tun muss, bevor es zum Drag wird, pro Zeigerart (Standardwerte siehe `ActivationOptions`). Drag-Bereiche, Listen, Bäume, Elemente und ziehbare Elemente können es überschreiben.","DnDProviderProps.keyboard":"Ziehen per Tastatur: Tasten und Schrittweite. `false` schaltet es aus; Escape bricht trotzdem jeden Drag ab.","DnDProviderProps.sensors":"Was Eingaben zu Drags macht. Standard `[pointerSensor, keyboardSensor]`: Lass einen weg, umhülle oder ersetze ihn oder füge eigene hinzu (`defineSensor`). Der Tastatursensor bricht außerdem jeden Drag mit Escape ab; `keyboard: false` schaltet seine Drags aus, behält das aber bei. Die Liste kann sich jederzeit ändern: Sensoren, die sie verlassen, stoppen und brechen dabei ihren Drag ab.","DnDProviderProps.haptics":"Vibration für Drags per Touch. Standard: eine kurze, wenn ein Drag nach dem langen Drücken beginnt; ein Objekt fügt weitere hinzu (`enter`, `drop`, `refuse`); `false` schaltet alle aus.","DnDProviderProps.copyModifier":"Taste (KeyboardEvent.key), die eine Verschiebung in eine Kopie verwandelt. Standard `'Alt'`; `null` deaktiviert das.","DnDProviderProps.overlayTo":"Wo das Overlay gerendert wird: ein Selektor oder ein Element. Standard `'body'`. Ein modaler `<dialog>` liegt über dem Rest der Seite: Drags darin brauchen es dort.","DnDProviderProps.overlayFit":"Größe des Overlays während des Ziehens. `'slot'` (Standard): Das Overlay folgt dem Slot, in dem das Element landen wird; über einer anderen Liste nimmt es also die Größe der Elemente dieser Liste an, und der Drop braucht keine Größenänderung. Es ändert seine Größe um den Zeiger herum, der immer beim selben Anteil der Box bleibt. `'source'`: Es behält die Größe des gezogenen Elements. Der Inhalt des Standard-Overlays wird in der neuen Größe neu angeordnet; er wird nie skaliert.","DnDProviderProps.overlayPreviews":"Multi-Drag: wie viele gezogene Elemente beim Aufnehmen einen Klon bekommen, das gegriffene und die anderen daneben in Drop-Reihenfolge. Standard 5; `'all'` klont jedes, das gerendert ist. Das Standard-Overlay zeigt die Klone und zählt den Rest (`+N`); in einem eigenen Layout rendert `DragPreview` für ein Element ohne Klon seinen Slot. Jeder Klon fliegt: bei einem Abbruch zurück zu seinem Element, bei einem Drop zu seinem Slot, in die Zone, in die ein Drop geht, einer nach dem anderen. Die Klone werden gemeinsam erstellt, mit einem Layout pro Snapshot-Durchlauf für alle, aber jeder kostet das Auslesen seiner Styles: Achte auf lange Elemente auf langsamen Handys.","DnDProviderProps.overlayTransition":"Wie das Overlay während eines Drags von einer Komponente zur anderen wechselt (das `overOverlay` eines Drop-Ziels übernimmt, ein `overlay`-Ref wird umgeschaltet): `true` (Standard) blendet sie in 150 ms über, `false` tauscht sie sofort, und ein Objekt sind die Props einer Vue-`<Transition>` um die Wurzel des Inhalts (`name`, `mode`, JS-Hooks für GSAP oder motion). Ohne `mode: 'out-in'` sind beide gleichzeitig zu sehen: Gib der ausgehenden `position: absolute` (`.<name>-leave-active`), damit sie sich in der Box stapeln.","DnDProviderProps.overlayClass":"Klassen für den Inhalt des Overlays (`[data-dnd-overlay-content]`), das Element, das die Overlay-Box füllt: das, das als Ganzes animiert wird, während die Bibliothek die Box bewegt und ihre Größe setzt. Eine Transition darauf läuft beim Aufnehmen von `@starting-style` aus und beim Landen zurück (`[data-dnd-overlay='dropping']`): Der Drop wartet auf sie. Einfaches CSS erreicht es außerhalb von `<style scoped>` (oder mit `:global(...)`), Tailwind mit `starting:` und `in-data-[dnd-overlay=dragging]:`.","DnDProviderProps.announcements":"Eigene Texte für einige Events (siehe `Announcements`); `false` lässt die Live-Region stumm.","DnDProviderProps.screenReaderInstructions":"Wie man per Tastatur zieht, von Screenreadern für jedes ziehbare Element vorgelesen (sein `aria-describedby`). Standard: englische Anweisungen für Leertaste, Enter, die Pfeiltasten und Escape.","DnDProviderProps.defaultStyles":"Das Standard-Aussehen einfügen: CSS ohne Spezifität in Layern, das Platzhalter und die Elemente, die ein Multi-Drag an ihrem Platz lässt, abblendet (`opacity: 0.4`). Standard `true`; `false` überlässt das Aussehen dir. Was Drags brauchen, wird in jedem Fall eingefügt: keine Textauswahl und kein Scroll-Anchoring während des Ziehens (virtuelle Listen sind darauf angewiesen), der Drag-Cursor (`--dnd-cursor`) und kein Link-Callout bei langem Drücken auf iOS.",DnDContext:"Ein Provider, wie `useDnDContext()` ihn zurückgibt, zur Übergabe an `provideDnDContext()`: Eine andere Vue-App (z. B. eine in einem Shadow Root gemountete) arbeitet dann mit demselben Provider. Opak: Er hat keine öffentlichen Member und ändert sich daher nie mit den Interna der Bibliothek.",OverlaySlotProps:"Was das Overlay zeigt: die Props des Slots `#overlay` des Providers und von Overlay-Komponenten (Option `overlay` von ziehbaren Elementen, sortierbaren Elementen, Listen und Bäumen).","OverlaySlotProps.active":`Der Drag.`,"OverlaySlotProps.items":`Alle gezogenen Elemente, das primäre zuerst: ein Overlay für den ganzen Multi-Drag.`,"OverlaySlotProps.over":"Das Drop-Ziel unter dem Drag. Während ein entschiedener Drop animiert wird, das Ziel, auf dem er landet (so, wie es beim Drop war); `null`, während ein abgebrochener Drag zurückfliegt.","OverlaySlotProps.accepted":"Ob `over` die gezogenen Elemente annimmt; `false`, wenn der Drag über nichts ist.","OverlaySlotProps.status":"`'dragging'`, dann `'dropping'`, während das Overlay landet (oder zurückfliegt).","OverlaySlotProps.mode":"Was ein Drop jetzt bewirken würde (siehe `DnDEvent.mode`): z. B. ein Plus zeigen, solange er kopiert.","OverlaySlotProps.to":"Wohin ein Drop die gezogenen Elemente jetzt legen würde, in einer sortierbaren Liste oder einem Baum: z. B. um das Overlay nach dem Ordner zu färben, in den ein Drag im Baum käme. Außerhalb aller Ziele ist es der Platz des Slots, an dem `dropOutside: 'placeholder'` (der Standard) sie lässt. `null`, wenn der Drop sie in keine Liste legen würde: über einem einfachen Drop-Ziel, über einer Liste, die sie ablehnt, außerhalb mit `dropOutside: 'cancel'` oder `'remove'`. Während ein entschiedener Drop animiert wird, der Platz, auf dem er landet.",OverlayProps:"Props einer Overlay-Komponente, für `defineProps<OverlayProps>()`.\n\nDie Komponente rendert innerhalb der Overlay-Box, die der Größe des Slots folgt (`overlayFit: 'slot'`) und diese beim Drop animiert. Gib dem Root-Element `width: 100%` (und `height: 100%`), damit es dieser Größe folgt; mit einer festen Größe behält die Komponente ihre eigene.",DragPreviewProps:"Props von `DragPreview`: der Standardklon eines gezogenen Elements, für eigene Overlays (eine `overlay`-Komponente oder den Slot `#overlay` des Providers), die mehrere Elemente selbst anordnen, z. B. `<DragPreview v-for=\"item in items\" :key=\"item.id\" :id=\"item.id\" />`.\n\nKlone werden beim Aufnehmen erstellt: vom gegriffenen Element und von den anderen, die in Drop-Reihenfolge daneben liegen, so viele wie `overlayPreviews` des Providers (standardmäßig 5; von denen, die zu diesem Zeitpunkt gerendert sind). Für jedes andere Element rendert `DragPreview` seinen Default-Slot in einem DOM-Element, das `class` und `style` so annimmt wie das eines Klons, oder nichts, wenn es keinen gibt. Der Klon füllt das DOM-Element aus, das beim Aufnehmen die Größe des Elements bekommt, inline gesetzt: Ändere sie mit `style` (`:style=\"{ width: '100%', height: '100%' }\"`), das durchgereicht wird; eine Klasse kann sie nicht überschreiben.\n\nBei einem sortierbaren Multi-Drag (`multiple: 'group'` oder `'gaps'`) landet die Vorschau eines anderen Elements als des gegriffenen mit dem Drop im Slot dieses Elements (bei einem Abbruch wieder auf seinem Platz), von wo auch immer das Layout sie hingesetzt hat: Mit `transform` gedrehte oder skalierte Wrapper werden unterwegs rückgängig gemacht, ihre Größe wird als Breite und Höhe animiert. Style die Vorschau selbst (Ecken, Schatten): Ihre Wrapper bleiben in der Box. Elemente ohne Klon werden stattdessen eingeblendet. In eine Zone (keine Liste) abgelegt, gehen die Vorschauen eine nach der anderen hinein, die Box zuletzt.","DragPreviewProps.id":"ID eines gezogenen Elements: eines aus `items` in `OverlayProps`.",SelectionStrategy:"- `'toggle'`: Elemente, die der Rahmen kreuzt, kehren ihren Zustand von vor dem Rahmen um;\n- `'select'`: Nur die Elemente innerhalb des Rahmens sind ausgewählt.",SelectionModifier:"Tasten (`KeyboardEvent.key` oder `.code`), die gedrückt sein müssen, damit ein Druck einen Rahmen aufzieht: alle oder `'some'` davon.","SelectionModifier.keys":"Die Tasten, als `KeyboardEvent.key` (`'Shift'`) oder `.code` (`'KeyA'`). Keine: Jeder Druck zieht einen Rahmen auf.","SelectionModifier.method":"`'every'`: Alle `keys` müssen gedrückt sein; `'some'`: Eine davon genügt.",SelectionAreaOptions:"Optionen von `makeSelectionArea`. Der Rahmen wählt in die Auswahl des Providers aus, die Multi-Drag und `selected` lesen (`useDnD().selection`). `modifier`, `strategy`, `accept` und `disabled` nehmen einen Wert, ein Ref oder einen Getter entgegen (`accept`: einen Wert oder ein Ref, eine Funktion ist eine Regel) und werden gelesen, wenn ein Druck einen Rahmen startet; `disabled` einzuschalten bricht auch einen laufenden ab.","SelectionAreaOptions.modifier":`Tasten, die gedrückt sein müssen, damit ein Druck einen Rahmen aufzieht. Standard: keine, jeder Druck auf die leere Fläche zieht einen auf.`,"SelectionAreaOptions.strategy":"Standard `'toggle'`.","SelectionAreaOptions.accept":`Welche ziehbaren Elemente der Rahmen auswählt; der Matcher der Drop-Ziele.`,"SelectionAreaOptions.disabled":"`true`: Ein Druck zieht keinen Rahmen auf.","SelectionAreaOptions.onSelected":`Der Rahmen ist beendet: Bekommt jede jetzt ausgewählte ID.`,SelectionAreaReturn:"Was `makeSelectionArea` zurückgibt.","SelectionAreaReturn.isSelecting":`Ein Rahmen wird gerade aufgezogen: Rendere ihn dann.`,"SelectionAreaReturn.style":`Style für das Element des Auswahlrechtecks (absolut, relativ zum Container).`,SensorDirection:`Pfeil eines Tastaturschritts.`,SortablePosition:"Eine Position in einer sortierbaren Liste, für `SensorDrag.place()` (und `moveItem` aus `@vue-dnd-kit/actions`). Nur Listen: Bäume platzieren Elemente über ihre eigenen Schlüssel.","SortablePosition.list":"ID der Liste (`SortableListOptions.id`). Standard: die Liste, in der das Element ist.","SortablePosition.index":`Index, auf dem das Element landet, gezählt ohne das Element selbst (ein Multi-Drag-Block zählt einmal). Auf die Liste begrenzt; Standard: das Ende.`,SensorActivation:"Was ein Sensor anfragt, wenn seine Eingabe ziehen will (`SensorContext.activate()`).","SensorActivation.target":"Wo die Eingabe gelandet ist: ein Element innerhalb eines ziehbaren Elements oder die ID eines ziehbaren Elements. Ein Element muss zu diesem Provider gehören; bei `'pointer'`-Drags muss es auf dem Handle liegen, wenn es eines gibt, und nicht auf einem interaktiven Kind (einem Button, einem Eingabefeld); bei `'keyboard'`-Drags muss es das Fokusziel des ziehbaren Elements sein (das Handle, sonst das ziehbare Element selbst) und kein editierbares Feld. Eine ID überspringt diese Prüfungen: Der Drag startet vom Element, wo auch immer die Eingabe war.","SensorActivation.type":"Wie sich der Drag bewegt. `'pointer'` (Standard): Er folgt den Punkten, die an `move()` übergeben werden, Ziele werden dort per Hit-Testing ermittelt, Container scrollen an ihren Rändern automatisch, und die Seite zeigt den Greif-Cursor. `'keyboard'`: Er bewegt sich mit `step()` und `place()` von Element zu Element, wie es die Pfeiltasten tun, Ziele werden ins Sichtfeld gebracht statt per Auto-Scroll angefahren, und der Fokus kehrt am Ende zum Element zurück. `Active.sensor` sagt, welcher Typ es ist.","SensorActivation.point":`Wo der Drag beginnt, in Viewport-Koordinaten. Standard: die Mitte des ziehbaren Elements.`,"SensorActivation.event":"Das Eingabe-Event. Es wird an `canDrag` des ziehbaren Elements übergeben: Ohne Event (ein Gamepad, ein programmatischer Drag) wird `canDrag` nicht gefragt. Ein `pointerType` von `'touch'` macht den Drag zu einem Touch-Drag (`haptics`).","SensorActivation.activation":"Worauf der Drag wartet, bevor er beginnt (`useDnD().status` ist bis dahin `'activating'`, mit seinem Fortschritt). Eine Zeigerart liest dafür die Option `activation` des ziehbaren Elements, dann die des Providers, dann die Standardwerte (Maus 4px, sofort bei einem Handle; Stift 4px; Touch ein langes Drücken von 200ms mit 5px Toleranz). Eine Aktivierungsbedingung wird so verwendet, wie sie ist. Standard: keine, der Drag beginnt sofort.","SensorActivation.onStart":`Der Drag hat begonnen, nach seiner Aktivierung: z. B. den Zeiger einfangen.`,"SensorActivation.onEnd":`Der Drag ist vorbei: Seine Aktivierung wurde abgebrochen, oder er wurde abgelegt oder (von wem auch immer) abgebrochen.`,"SensorActivation.onResume":"Der Drop, den der Sensor angefragt hat, hat nicht stattgefunden, und der Drag geht weiter (`onBeforeDrop` hat `'continue'` geantwortet): `move`, `drop` und `cancel` gelten wieder. Ein Zeigersensor lässt das Element bis zum nächsten Loslassen dem Zeiger folgen.",SensorDragState:"- `'pending'`: wartet auf die Aktivierungsbedingung;\n- `'dragging'`: vom Start, bis über den Drop entschieden ist oder der Drag abgebrochen wird;\n- `'ended'`: Die Aktivierung wurde abgebrochen, oder der Drag wurde abgelegt oder abgebrochen, vom Sensor oder durch etwas anderes (Escape, ein verborgener Tab, `useDnD().cancel()`, das Unmounten des Providers).",SensorStepOptions:"Optionen von `SensorDrag.step()`.","SensorStepOptions.event":"Der Tastendruck, der an `getKeyboardCoordinates` der Monitore übergeben wird. Standard: ein keydown der Pfeiltaste.","SensorStepOptions.fast":"Ein größerer Schritt bei freien Drags (wie mit Shift). Standard: `event.shiftKey`.",SensorDrag:"Ein Drag eines Sensors, von `activate()` bis zu seinem Ende. Jeder Aufruf wird ignoriert, sobald er nicht mehr zutrifft: Bewegungen vor dem Start oder nach dem Ende, ein zweites `drop()`.","SensorDrag.id":`ID des gezogenen Elements.`,"SensorDrag.type":"Wie sich der Drag bewegt, wie von `activate()` angefragt (`SensorActivation.type`).","SensorDrag.state":`Wo der Drag steht: wartet auf seine Aktivierung, zieht oder ist beendet.`,"SensorDrag.started":`Der Drag hat begonnen, auch wenn er inzwischen geendet hat (der Zeigersensor schluckt den Klick, der darauf folgt).`,"SensorDrag.move":`Die Eingabe hat sich bewegt. Im Wartezustand wird die Aktivierungsbedingung geprüft (eine Bewegung über ihre Toleranz hinaus bricht sie ab); während des Ziehens geht der Drag dorthin. Zeiger-Drags übernehmen eine Position pro Frame; Tastatur-Drags bewegen sich sofort, nach den Schritten davor.`,"SensorDrag.step":"Tastatur-Drags: ein Pfeilschritt, wie ihn die Pfeiltasten des Tastatursensors ausführen (das nächste Element einer Liste, das nächste annehmende Ziel im Modus `'droppables'` oder `keyboard.step` Pixel). Schritte werden eingereiht: Jeder läuft, sobald der vorherige gerendert ist, und eine wiederholte Taste (`event.repeat`) wird übersprungen, solange noch einer läuft. Zeiger-Drags ignorieren ihn.","SensorDrag.place":"Setzt das Element an eine Position einer sortierbaren Liste, wie es Tastaturbewegungen tun (andere Listen nehmen es nur, wenn sie es annehmen), und bewegt den Drag an seinen neuen Platz. Liefert `false`, wenn keine Liste es dort nimmt. In Tastatur-Drags wie `step()` eingereiht.","SensorDrag.drop":"Legt ab: Eine wartende Aktivierung wird stattdessen abgebrochen. Liefert sein Ergebnis, sobald der Drag geendet hat und gelandet ist: `true`, wenn der Drop ausgeführt wurde, `false`, wenn er abgelehnt wurde (von einem Ziel, von `onBeforeDrop`) oder es nichts abzulegen gab.","SensorDrag.cancel":`Bricht den Drag ab (er fliegt zurück) oder bricht eine wartende Aktivierung ab.`,SensorContext:`Was ein Sensor vom Provider bekommt, in dem er läuft.`,"SensorContext.props":"Die Props des Providers (z. B. `activation`, `keyboard`). Lies sie, wenn du sie brauchst: Sie können sich ändern.","SensorContext.status":`Der Drag-Status des Providers, egal welcher Sensor den Drag ausführt.`,"SensorContext.drag":"Der Drag des Providers, wartend oder laufend, egal welcher Sensor ihn gestartet hat; `null`, wenn es keinen gibt. Sensoren können die Drags der anderen steuern: Der Tastatursensor bewegt jeden Tastatur-Drag und legt ihn ab, z. B. einen, den ein „Move“-Button aufgenommen hat (`@vue-dnd-kit/actions`).","SensorContext.activate":"Fragt an, ein Element zu ziehen. Der Provider prüft, dass er frei ist (immer nur ein Drag gleichzeitig, keiner, während ein Drop landet), dass das Ziel ein eigenes ziehbares Element ist, das nicht deaktiviert ist, wo die Eingabe gelandet ist (siehe `target`) und `canDrag` des ziehbaren Elements; dann wartet er auf die Aktivierungsbedingung und startet den Drag. Gibt den Drag zurück (wartend oder bereits laufend, wenn es nichts abzuwarten gibt) oder `null`, wenn kein Drag beginnen darf.","SensorContext.cancel":`Bricht den Drag oder die wartende Aktivierung des Providers ab, egal welcher Sensor ihn ausführt (Escape, ein verborgener Tab).`,"SensorContext.onWindow":"Führt `setup` für jedes Fenster aus, in dem der Provider arbeitet: für das der Seite sofort und für jedes andere Fenster der App, in dem Elemente des Providers sind (ein mit `window.open` geöffnetes Popup, in das ein Teleport rendert, siehe `DnDState.addWindow`), sobald es dazukommt. Höre dort auf die Eingaben dieses Fensters (`useEventListener(view.document, …)`): Das wird aufgeräumt, wenn das Fenster sich schließt oder der Sensor stoppt, ebenso wie die Aufräumfunktion, die `setup` zurückgibt.",Sensor:"Eingabe, die Drags startet: Zeiger, Tastatur oder deine eigene (ein Gamepad, ein Joystick auf dem Bildschirm, Sprache, per Skript gesteuerte Drags). `setup` läuft einmal pro Provider, nur im Browser, innerhalb eines Effect Scopes, der mit dem Provider endet (oder wenn der Sensor `sensors` verlässt oder die Komponente, die `useSensor` aufgerufen hat, unmountet wird). Registriere Listener mit `useEventListener` oder gib eine Aufräumfunktion zurück; ein Drag, der dann noch läuft, wird abgebrochen.\n\nUm einen Sensor zu umhüllen, führe sein `setup` mit einem eigenen Kontext aus. `Object.create(context, { activate: { value: … } })` behält die Live-Getter (`status`, `drag`, `props`): Ein Spread würde sie einfrieren.","Sensor.name":`Zum Debuggen.`,"Sensor.setup":"Beginnt, auf die Eingabe zu hören, einmal pro Provider: Rufe `context.activate()` auf, wenn sie ziehen will. Darf eine Aufräumfunktion zurückgeben, die läuft, wenn der Sensor stoppt.",SortableStrategy:"Wie eine Liste ihre Elemente anordnet: als Spalte (`'vertical'`), als Zeile (`'horizontal'`) oder als umbrechendes Raster (`'grid'`).",SortableBehavior:"Was das Hovern über einem Element bewirkt: `'sort'` macht Platz (die Elemente dazwischen verschieben sich), `'swap'` tauscht die beiden Elemente.",SortablePlaceholder:"Wie ein Drag zeigt, wohin er geht: `'item'`, der Slot des gezogenen Elements wandert durch die Liste; `'indicator'`, die Liste bleibt, wie sie ist, und `indicator` sagt, wohin der Drop geht (du zeichnest die Linie).",MultipleMode:"Was die anderen ausgewählten Elemente bei einem Multi-Drag tun:\n- `'group'`: Sie verlassen ihre Plätze und begleiten das aktive Element als zusammenhängende Platzhalter, sodass die Liste schon beim Hovern das Ergebnis des Drops zeigt;\n- `'gaps'`: Sie bleiben bis zum Drop an ihrem Platz;\n- `'stack'`: Sie fallen im Overlay zusammen.\n\nDas Standard-Overlay zeigt die gezogenen Elemente in einer Spalte entlang der Liste (`'group'`, `'gaps'`; eine Zeile in horizontalen Listen, ein Stapel hinter dem aktiven Element in Rastern) oder das aktive Element mit einer Anzahl (`'stack'`).",DropOutside:"Was ein Drop außerhalb aller Ziele bewirkt: `'placeholder'` behält die Elemente dort, wo ihr Slot ist, `'cancel'` schickt sie zurück, `'remove'` nimmt sie aus ihrer Liste.",SortablePutContext:"Womit ein `group.put` in Form einer Funktion aufgerufen wird: die Elemente, die in die Liste kämen.","SortablePutContext.keys":`Schlüssel der Elemente.`,"SortablePutContext.items":"Die Elemente (bei einem einfachen ziehbaren Element das, das `createItem` erzeugt hat).","SortablePutContext.types":`Die Typen der Elemente, zusammen.`,"SortablePutContext.from":"Quellliste, `null` für externe ziehbare Elemente.","SortablePutContext.to":`ID der gefragten Liste.`,SortableGroupOptions:`Die Gruppe einer Liste: die Listen, die Elemente austauschen, und ob Elemente diese verlassen und in sie kommen dürfen.`,"SortableGroupOptions.name":`Listen und Bäume mit demselben Namen tauschen Elemente aus.`,"SortableGroupOptions.pull":"Ob Elemente diese Liste verlassen können: verschieben, kopieren (`'clone'`, eine Palette) oder gar nicht.","SortableGroupOptions.put":"Ob Elemente in diese Liste kommen können: `true` (Standard), `false`, ein Typ oder Typen, die die Elemente haben müssen (wie das `accept` eines Drop-Ziels: mit `acceptMode` alle oder einige), oder eine Funktion des Drags.",SortableItems:"Eine Quelle sortierbarer Elemente. Ein beschreibbares Ref: Die Bibliothek schreibt jeden Drop hinein. Eine schreibgeschützte Quelle (ein Getter, ein readonly Ref, ein computed: ein unveränderlicher Store, Server-State, ein Store, der nur über Actions geändert wird): Du wendest jeden Drop aus `event.result` an, nach `event.preventDefault()` (siehe `SortableDropEvent`).",SortableDropEvent:"Ein Drop auf eine sortierbare Liste oder einen Baum. Seine Hooks laufen in dieser Reihenfolge: `onBeforeDrop` entscheidet, `onDrop` wird informiert, dann schreibt die Standardaktion `result` in die `items` jeder Liste, die darin genannt ist, und das Overlay landet. `preventDefault()` in einem der beiden Hooks überspringt dieses Schreiben, sodass du `result` selbst anwenden kannst.","SortableDropEvent.keys":`Schlüssel der gezogenen Elemente.`,"SortableDropEvent.items":"Die Elemente, die landen: die gezogenen, ihre Kopien (`mode: 'copy'`) oder das Element, das `createItem` erzeugt hat (`'insert'`).","SortableDropEvent.accepted":"Schlüssel, die durchgehen: alle, sofern die Liste oder `onBeforeDrop` nicht nur einige annimmt.","SortableDropEvent.rejected":`Schlüssel, die dorthin zurückfliegen, wo sie waren.`,"SortableDropEvent.from":"Wo der Drag begann: die Liste und der Index des aktiven Elements. `list` ist `null` bei einem einfachen ziehbaren Element von außen.","SortableDropEvent.to":"`index` ist -1, wenn nichts gelandet ist: Die Elemente haben ihre Listen verlassen (`e.source.remove()`, `dropOutside: 'remove'`).","SortableDropEvent.sameList":`Der Drop bleibt in der Liste, in der der Drag begann.`,"SortableDropEvent.mode":"Was der Drop bewirkt (siehe `DragMode`).","SortableDropEvent.partner":"`mode: 'swap'`: das Element, mit dem das gezogene getauscht wurde. Es hat sich in die Gegenrichtung bewegt, von `from`, dem Platz, den das gezogene Element eingenommen hat (`to` oben), nach `to`, dem Platz, an dem das gezogene Element begonnen hat (`from` oben); zwischen Listen in die Liste des gezogenen Elements.","SortableDropEvent.result":"Die neuen Elemente jeder Liste, die der Drop ändert, nach Listen-ID: genau das, was das Standard-Schreiben in ihre `items` setzt, als neue Arrays. Verschiebungen, Kopien, erstellte Elemente, eine teilweise Annahme, beide Seiten eines Tauschs und entfernte Elemente (`e.source.remove()` in einem Ziel innerhalb eines Elements, eine Papierkorb-Zone, `dropOutside: 'remove'`) sind alle darin enthalten; eine Liste, die der Drop unverändert lässt, nicht. Der Eintrag eines Baums ist ein neues Wurzel-Array: Die Knoten auf den geänderten Pfaden sind Kopien (`withChildren`), unberührte Teilbäume werden geteilt, deine Knoten werden nie mutiert. In `onBeforeDrop` ist es der Drop, wie er vor der Antwort des Hooks aussieht (einige Schlüssel zurückzugeben ändert ihn); `onDrop` bekommt den endgültigen.","SortableDropEvent.preventDefault":"Überspringt das Standard-Schreiben, in jede Liste in `result` (nur einige zu schreiben würde Elemente verlieren oder duplizieren). Wende `result` selbst in `onDrop` an oder bevor ein asynchrones `onBeforeDrop` aufgelöst wird, und das Overlay landet in der neuen Reihenfolge. Wird es nirgends angewendet, bleiben die Listen, wie sie waren, und das Overlay fliegt zurück (Kopien und erstellte Elemente, die noch keinen Platz haben, werden ausgeblendet).","SortableDropEvent.defaultPrevented":"`preventDefault()` wurde aufgerufen, in `onBeforeDrop` oder `onDrop`.","SortableDropEvent.external":"Ein Drag von außerhalb der Seite (`external`): was er trug, mit seinen Daten (er wurde abgelegt).",SortableIndicator:"Wohin der Drop mit `placeholder: 'indicator'` geht: Die Liste bewegt sich nicht, du zeichnest die Linie.","SortableIndicator.list":`ID der Liste (oder des Baums), in die der Drop geht.`,"SortableIndicator.index":`Einfügeposition in der Liste, wie sie gerendert ist.`,"SortableIndicator.key":"Element, an dem der Indikator hängt; `null` in einer leeren Liste.","SortableIndicator.side":"Seite von `key`, an der die Linie erscheint. `'inside'` (Bäume): Der Zeiger ist über der Mitte einer Zeile, die die gezogenen Knoten aufnimmt; der Drop geht als ihr erstes Kind hinein. `'swap'` (`behavior: 'swap'`): `key` ist das Element, mit dem der Drop tauscht; markiere das Element selbst.","SortableIndicator.depth":`Bäume: Tiefe, die die abgelegten Knoten bekommen (Wurzeln sind 0), z. B. um die Linie einzurücken.`,"SortableIndicator.parentKey":"Bäume: Elternknoten, den die abgelegten Knoten bekommen, `null` auf der Wurzelebene.",SortableListOptions:"Optionen von `makeSortableList`. Eine Komponente kann mehrere Listen (und Bäume) erstellen: Jedes darin gerenderte Element gehört zur innersten, deren DOM-Element es enthält.\n\nOptionen nehmen einen Wert, ein Ref oder einen Getter entgegen (`overlay`, `overOverlay`, `dropAnimation`, `overDropAnimation`, `animation`: einen Wert oder ein Ref) und werden gelesen, wenn die Liste sie braucht, sodass eine Änderung spätestens ab dem nächsten Drag gilt. Ausnahmen: `id` und `group` werden einmal gelesen, wenn die Liste erstellt wird; `items` ist das Modell selbst; Funktionen (`getKey`, `filter`, `clone`, `createItem`, die Callbacks) werden so übergeben, wie sie sind.","SortableListOptions.items":"Die Quelle der Wahrheit. Ein beschreibbares Ref bekommt beim Drop das neue Array, direkt nach `onDrop`. Eine schreibgeschützte Quelle (ein Getter, ein readonly Ref, ein computed) kann das nicht: Rufe `event.preventDefault()` auf und wende `event.result` selbst an. Entwicklungs-Builds warnen dort vor einem Drop, der der Bibliothek überlassen wird und dann nichts ändert.","SortableListOptions.getKey":"Standard: `item.id` oder bei Primitiven das Element selbst. Liefert auch die Schlüssel für `makeSortableItem({ item })`.","SortableListOptions.filter":"Zeigt nur die Elemente, für die es `true` zurückgibt (eine Suche, ein Tag): `items` (das zurückgegebene) enthält sie, und ein Drag sortiert unter ihnen. Die anderen behalten ihre Plätze in der Quelle: Ein Drop schreibt das ganze Array, jedes ausgeblendete Element weiterhin hinter dem gezeigten, dem es folgte (hinter dem nächsten, das an seinem Platz blieb, wenn jenes sich bewegt hat). Reaktiv: Was es liest (ein Ref mit der Suchanfrage), gilt sofort. `e.to.index` und `activeIndex` zählen die gezeigten Elemente.","SortableListOptions.id":"Standard: `useId()`, stabil zwischen Server- und Client-Rendering. Wird einmal gelesen.","SortableListOptions.label":"Der lesbare Name der Liste: Screenreader-Texte nennen ihn statt ihrer ID (`position 2 of 5 in Garden`).","SortableListOptions.data":"Alles, was es über die Liste als Drop-Ziel zu sagen gibt: Events tragen es als `over.data`, solange ein Drag über ihr ist.","SortableListOptions.activation":"Wie ein Druck auf die Elemente dieser Liste einen Drag startet, statt `activation` des Providers (die eigene eines Elements gewinnt). Wird gelesen, wenn ein Druck beginnt.","SortableListOptions.overlay":"Overlay-Komponente für die Elemente dieser Liste (das eigene `overlay` eines Elements gewinnt). Sie bekommt `OverlayProps` und bleibt für den ganzen Drag erhalten, auch über anderen Listen, sofern das Ziel unter dem Drag kein eigenes Overlay hat (`overOverlay`). Ein mitten im Drag umgeschaltetes Ref tauscht sie sofort.","SortableListOptions.overOverlay":"Was das Overlay zeigt, während ein Drag, den diese Liste annimmt, über ihr ist, egal aus welcher Liste er kommt: eine Komponente, die `OverlayProps` und das eigene Overlay des Drags als Standard-Slot bekommt (siehe `DroppableOptions.overOverlay`). Wird live gelesen.","SortableListOptions.dropAnimation":"Wie das Overlay landet, wenn ein Drag der Elemente dieser Liste endet, statt der `dropAnimation` des Providers (die eigene eines Elements gewinnt; die eines Drop-Ziels gewinnt gegen beide). Wird beim Drop gelesen.","SortableListOptions.overDropAnimation":"Wie das Overlay landet, wenn es in diese Liste abgelegt wird, egal aus welcher Liste es kommt: gewinnt gegen die `dropAnimation` des gezogenen Elements und des Providers. Wird beim Drop gelesen.","SortableListOptions.modifiers":"Modifier für Drags der Elemente dieser Liste, angewendet nach den `modifiers` des Providers (die eigenen `modifiers` eines Elements gewinnen): z. B. `[restrictToVerticalAxis]`, um die Elemente einer vertikalen Liste auf ihrer Achse zu halten. Wird beim Start des Drags gelesen.","SortableListOptions.axis":"Beschränkt Drags der Elemente dieser Liste auf eine Achse: `'y'` für eine vertikale Liste, `'x'` für eine horizontale (das eigene `axis` eines Elements gewinnt). Die Sperre kommt nach den Modifiern, sie gilt also, egal was diese tun. Wird beim Start des Drags gelesen.","SortableListOptions.group":`Listen mit demselben Gruppennamen tauschen Elemente aus. Standard: eine eigene Gruppe. Wird einmal gelesen.`,"SortableListOptions.acceptMode":"Multi-Drag von Elementen mehrerer Typen: `'all'` (Standard) oder `'some'` müssen angenommen werden (`group.put`).","SortableListOptions.strategy":"Standard `'vertical'`.","SortableListOptions.behavior":"`'swap'`: Das gezogene Element tauscht live den Platz mit dem Element unter dem Zeiger; wieder darauf oder aus den Listen hinaus zu ziehen macht das rückgängig. Listen einer Gruppe, die beide tauschen, tauschen Elemente untereinander aus: Das Element unter dem Zeiger wandert an den Platz des gezogenen, es muss also seine Liste verlassen (`group.pull: true`) und in die des gezogenen Elements kommen können (`group.put`). Multi-Drag sortiert stattdessen. Standard `'sort'`.","SortableListOptions.placeholder":"`'indicator'`: Die Liste bewegt sich nicht, `indicator` sagt, wohin der Drop geht. Standard `'item'`.","SortableListOptions.multiple":"Multi-Drag-Modus der Drags, die in dieser Liste beginnen. Standard `'group'`. Wird beim Start des Drags gelesen.","SortableListOptions.sort":"`false`: Elemente lassen sich innerhalb dieser Liste nicht neu ordnen (Paletten).","SortableListOptions.clone":"Erstellt Kopien (`pull: 'clone'`, Modifier-Taste zum Kopieren). Zum Kopieren erforderlich.","SortableListOptions.createItem":"Nimmt einfache ziehbare Elemente von außen an: erstellt das einzufügende Element. Mit der Tastatur holt ein Pfeil in Richtung der Liste das ziehbare Element herein (auf seiner Höhe, wie bei Bewegungen zwischen Listen), und das erstellte Element bewegt sich dann wie jedes andere von Slot zu Slot.\n\nBei einem Drag von außerhalb der Seite (`external`) wird es zweimal gefragt: während er gehalten wird, nach dem Element, das zeigt, wo er hinkommt (dann sind nur `active.external.fileTypes` und `types` bekannt), und beim Drop, mit seinen Daten (`active.external.ready`), nach dem, was eingefügt wird. Ein Array von Elementen wird komplett dort eingefügt, wo der Slot war: eines pro Datei.","SortableListOptions.external":"Nimmt Drags von außerhalb der Seite an: Dateien, Links, Text (siehe `ExternalAccept`). Die Liste macht ihnen Platz wie einem einfachen ziehbaren Element, mit `createItem`, das sie dafür braucht. Elemente ihrer Gruppe, die aus einem anderen Fenster der App hereingezogen werden (`native`), brauchen keine der beiden Optionen: Sie kommen als sie selbst hinein. Ein Wert, ein Ref oder ein Getter, live gelesen.","SortableListOptions.dropOutside":"Ein Drop außerhalb aller Ziele: die Elemente dort behalten, wo der Platzhalter ist, abbrechen oder sie entfernen. Standard `'placeholder'` (`'cancel'` mit `placeholder: 'indicator'`). Wird beim Drop gelesen.","SortableListOptions.animation":"FLIP-Animation dieser Liste; Standard: `animation` des Providers. Ein Wert oder ein Ref (eine Funktion ist eine eigene Animation).","SortableListOptions.animateChanges":"Animiert Änderungen von `items`, die kein Drag ausgelöst hat: hinzugefügte, entfernte, verschobene und gefilterte Elemente (siehe `AutoAnimation`). Standard: `animateChanges` des Providers, aus, sofern dort nicht gesetzt. Wird gelesen, wenn sich `items` ändert.","SortableListOptions.animateSize":"Die eigene Größe der Liste folgt ihren Elementen: Wenn ein Drag ein Element hereinbringt oder herausnimmt (und beim Drop und bei den Änderungen, die `animateChanges` zeigt), wächst oder schrumpft sie mit Dauer und Easing von `animation` auf ihre neue Größe, statt zu springen, und was um sie herum ist, bewegt sich mit. Standard `true`; `false` lässt sie springen. Wird bei jeder Änderung gelesen.","SortableListOptions.autoScroll":"Überschreibt `autoScroll` des Providers für den Scroll-Container dieser Liste. Wird beim Start des Drags gelesen.","SortableListOptions.dropzone":`Das Element, das Drops für die Liste annimmt, standardmäßig das Listenelement selbst: z. B. die ganze Spalte um eine kurze Liste von Karten, sodass eine Karte, die unterhalb der letzten losgelassen wird, trotzdem in der Liste landet (an ihrem Ende). Die Elemente bleiben im Listenelement.`,"SortableListOptions.disabled":"`true`: Ihre Elemente können nicht gezogen werden, und sie nimmt keine Elemente an.","SortableListOptions.onBeforeDrop":"Wird vor einem Drop in diese Liste gefragt und bevor `dropOutside: 'remove'` ihre Elemente herausnimmt: `false` lehnt ihn ab (die Elemente fliegen zurück), einige Schlüssel nehmen nur diese an. Darf asynchron sein: Das Overlay wartet dort, wo es abgelegt wurde. Auch ein Fehler lehnt den Drop ab. Siehe `SortableDropEvent` für `result` und `preventDefault`.","SortableListOptions.onDrop":"Wird aufgerufen, sobald ein Drop in diese Liste angenommen ist, bevor er geschrieben wird: `items` enthält noch die alte Reihenfolge, `event.result` die neue. Synchron: Das Schreiben folgt, sobald es zurückkehrt, sofern es nicht `event.preventDefault()` aufgerufen hat. Wird auch für die Liste aufgerufen, aus der die Elemente kamen, wenn sie entfernt werden (`to.index` ist -1).",SortableListReturn:"Was `makeSortableList` zurückgibt.","SortableListReturn.id":"Die ID der Liste: die Option `id` oder die dafür erzeugte.","SortableListReturn.items":`Entwurfsreihenfolge: Rendere das, nicht das Quell-Array.`,"SortableListReturn.isOver":`Ein Drag ist über der Liste.`,"SortableListReturn.isAccepting":`Etwas wird gezogen, und diese Liste nimmt es an.`,"SortableListReturn.indicator":"Indikator-Modus: wohin der Drop in dieser Liste geht; `null`, wenn nicht hier.","SortableListReturn.activeKey":"Die Zeile, die ein Virtualizer gemountet halten muss: der Slot, solange er in dieser Liste ist (eine Kopie, ein erstelltes Element), sonst das gezogene Element; `null` ohne Drag.","SortableListReturn.activeIndex":`Index des aktiven Elements im Entwurf dieser Liste, -1, wenn es nicht hier ist.`,"SortableListReturn.activeSize":`Größe des gezogenen Elements beim Start des Drags: z. B. für die Größe einer virtuellen Zeile, die es hält.`,"SortableListReturn.captureLayout":`Animiert Layoutänderungen, die nicht die Bibliothek verursacht hat (z. B. ein erneutes Messen durch einen Virtualizer).`,SortableItemOptions:"Übergib `id` oder `item` (`id` gewinnt, wenn beide angegeben sind). Sortierbare Schlüssel müssen aus den Daten kommen: Eine automatische ID würde sich ändern, sobald die Komponente neu erstellt wird (in eine andere Liste verschoben, von einer virtuellen Liste wiederverwendet), und der Drag würde das Element verlieren.\n\nOptionen außer `canDrag` nehmen einen Wert, ein Ref oder einen Getter entgegen (`overlay`, `dropAnimation`: einen Wert oder ein Ref) und bedeuten dasselbe wie bei `makeDraggable`. Es gibt kein `keyboardMode`: Die Tastatur bewegt ein sortierbares Element von Slot zu Slot.","SortableItemOptions.id":`Schlüssel des Elements in seiner Liste. Ein Getter hält ihn in virtuellen Listen aktuell.`,"SortableItemOptions.item":"Das Datenelement, das dieses Element rendert, z. B. `() => props.task`. Sein Schlüssel kommt aus `getKey` der zugehörigen Liste (oder des Baums), standardmäßig `item.id`.","SortableItemOptions.overlay":"Overlay-Komponente für dieses Element; gewinnt gegen `overlay` der Liste. Ein mitten im Drag umgeschaltetes Ref tauscht sie sofort.","SortableItemOptions.dropAnimation":"Wie das Overlay landet, wenn ein Drag dieses Elements endet; gewinnt gegen die `dropAnimation` der Liste. Wird beim Drop gelesen.","SortableItemOptions.modifiers":"Modifier für Drags dieses Elements, nach denen des Providers; gewinnen gegen `modifiers` der Liste.","SortableItemOptions.axis":"Beschränkt Drags dieses Elements auf eine Achse (`'x'`, `'y'`); gewinnt gegen `axis` der Liste.","SortableItemOptions.handle":`Element oder Selektor innerhalb des Elements, der den Drag startet (und die Attribute bekommt).`,"SortableItemOptions.disabled":"`true`: Das Element kann nicht gezogen werden (wie jedes Element einer deaktivierten Liste).","SortableItemOptions.type":"Sein Typ oder seine Typen, für `group.put`-Regeln und das `accept` von Drop-Zielen. Standard: der Name der Gruppe seiner Liste.","SortableItemOptions.data":"Alles, was der Drag mitführen soll: Events und Drop-Ziele lesen es als `active.data`.","SortableItemOptions.label":"Der lesbare Name des Elements: Screenreader-Texte nennen ihn statt seines Schlüssels (`Picked up Tomato at position 2 of 5 in Garden`). Events tragen ihn als `active.label` und in `items`.","SortableItemOptions.activation":"Überschreibt `activation` seiner Liste (oder seines Baums) und des Providers. Wird gelesen, wenn ein Druck beginnt.","SortableItemOptions.canDrag":`Zusätzliche Bedingung, z. B. nur ziehen, solange eine Taste gedrückt ist.`,"SortableItemOptions.attributes":"Setzt role-/tabindex-/aria-*-Attribute (Standard `true`) und überschreibt nie deine eigenen. Live: Ausschalten entfernt, was die Bibliothek gesetzt hat.","SortableItemOptions.native":"Ein Maus-Drag des Elements ist der eigene Drag des Browsers, der die Seite verlassen kann (siehe `DraggableOptions.native`). Er trägt auch das Element: Die Listen seiner Gruppe in einem anderen Fenster der App nehmen es an, und wenn eine das tut, verlässt es diese Liste (`'move'`).",SortableItemReturn:"Was `makeSortableItem` zurückgibt.","SortableItemReturn.isDragging":`Dieses Element wird gezogen (auch true für die anderen Elemente eines Multi-Drags), oder sein Overlay landet noch.`,"SortableItemReturn.isPlaceholder":"Dieses Element ist ein Slot, in dem ein gezogenes Element landen wird: der des aktiven Elements und im Multi-Drag-Modus `'group'` die Slots der Elemente, die mit ihm wandern.","SortableItemReturn.selected":`Es ist in der Auswahl des Providers: Ein Drag eines ausgewählten Elements trägt sie alle. Setze den Wert, um es aus- oder abzuwählen.`,"SortableItemReturn.indicator":"Indikator-Modus: `indicator` der Liste, solange er an diesem Element hängt, sonst `null`. `side` sagt, wo die Linie erscheint; in Bäumen sagen `depth` und `parentKey`, wo der Drop landet (`side: 'inside'`: in diesem Element).","SortableItemReturn.index":`Index im gerenderten Entwurf, -1, wenn unbekannt.`,TreeNesting:"Wie ein Drag im Baum seine Tiefe wählt: `'offset'`, danach, wie weit er sich seitlich bewegt (`indentation` pro Ebene); `'hover'`, durch Hovern über der Mitte einer Zeile, die ihn als Kind aufnimmt; `'both'`.",FlatNode:"Ein sichtbarer Knoten eines Baums, wie `items` des Baums sie auflistet: Rendere sie der Reihe nach, eingerückt nach `depth`.","FlatNode.key":"Der Schlüssel des Knotens (`getKey`).","FlatNode.item":`Dein Knoten.`,"FlatNode.depth":`Seine Tiefe: Wurzeln haben 0. Der gezogene Knoten hat seine projizierte Tiefe.`,"FlatNode.parentKey":"Schlüssel seines Elternknotens; `null` bei einer Wurzel.","FlatNode.index":`Index unter den Geschwistern.`,"FlatNode.hasChildren":`Er hat Kinder, angezeigt oder nicht.`,"FlatNode.collapsed":"Seine Kinder sind ausgeblendet (sein Schlüssel ist in `collapsed`).",TreeProjection:`Wo der gezogene Knoten in einem Baum landen würde.`,"TreeProjection.depth":`Die Tiefe, die er bekäme (Wurzeln haben 0).`,"TreeProjection.parentKey":"Der Knoten, unter den er käme; `null` auf der Wurzelebene.",SortableTreeDropEvent:"Drop-Event eines Baums. `index` ist die Position unter den Geschwistern unter `parentKey` (`from`: vor der Verschiebung; `to`: danach, wobei der Knoten bereits von seinem alten Platz entfernt ist). `from.parentKey` ist `null` für Wurzelknoten und für Elemente aus einer anderen Liste. Ein Multi-Drag verschiebt `keys` (jeden mit seinem Teilbaum) nebeneinander: `from` ist, wo der Knoten war, der den Drag anführt (der gegriffene oder der ausgewählte Knoten, in dem er mitfährt), `to`, wo der erste von ihnen landet. Eine Kopie (`mode: 'copy'`) lässt die Knoten, wo sie sind, und fügt `items` ein, ihre Kopien; ein einfaches ziehbares Element (`mode: 'insert'`) den Knoten, den `createItem` erstellt hat.","SortableTreeDropEvent.from":`Wo der Knoten war, der den Drag anführt: sein Baum, sein Index unter seinen Geschwistern, sein Elternknoten.`,"SortableTreeDropEvent.to":`Wo der erste abgelegte Knoten landet: sein Baum, sein Index unter seinen neuen Geschwistern, sein neuer Elternknoten.`,SortableTreeOptions:"Optionen von `makeSortableTree`. Ein Multi-Drag verschiebt die ausgewählten Knoten als einen Block, jeden mit seinem Teilbaum, an einen Platz und eine Tiefe (in Dokumentreihenfolge); ein ausgewählter Knoten innerhalb eines anderen ausgewählten fährt in dessen Teilbaum mit. Das gilt auch für den gegriffenen Knoten (wie in VS Code): Er bleibt innerhalb des ausgewählten Knotens, in dem er liegt, und dieser bewegt sich mit seinem Teilbaum, während das Overlay auf der gegriffenen Zeile bleibt. `canNest` und `maxDepth` gelten für den ganzen Block.\n\nDie anderen Optionen bedeuten dasselbe wie bei `makeSortableList`. Sie nehmen einen Wert, ein Ref oder einen Getter entgegen (`overlay`, `overOverlay`, `animation`, `dropAnimation`, `overDropAnimation`: einen Wert oder ein Ref) und werden gelesen, wenn der Baum sie braucht, sodass eine Änderung spätestens ab dem nächsten Drag gilt. Ausnahmen: `id` und `group` werden einmal gelesen, wenn der Baum erstellt wird; `items` ist das Modell selbst; Funktionen (`getKey`, `getChildren`, `setChildren`, `canNest`, `clone`, `createItem`, die Callbacks) werden so übergeben, wie sie sind.","SortableTreeOptions.items":"Die Wurzelknoten. Ein beschreibbares Ref: Beim Drop gibt die Bibliothek den geänderten Knoten ihre neuen Kinder (`setChildren`) und schreibt ein neues Wurzel-Array. Eine schreibgeschützte Quelle (ein Getter, ein readonly Ref, ein computed): Rufe `event.preventDefault()` auf und wende `event.result` selbst an (wie bei `SortableListOptions.items`).","SortableTreeOptions.getKey":"Standard: `node.id`. Liefert auch die Schlüssel für `makeSortableItem({ item })`, Kopien und erstellte Knoten.","SortableTreeOptions.getChildren":"Die Kinder eines Knotens. Standard: `node.children`.","SortableTreeOptions.setChildren":"Wie das Standard-Schreiben einem Knoten seine neuen Kinder gibt. Standard: `node.children = children`.","SortableTreeOptions.withChildren":"Eine Kopie von `node` mit `children`, für `event.result`: ein neuer Baum, der deine Knoten unverändert lässt (das Standard-Schreiben läuft weiterhin über `setChildren`). Standard: `{ ...node }`, dem die Kinder über `setChildren` gegeben werden (`{ ...node, children }` ohne `setChildren`). Übergib es für Klasseninstanzen und Knoten, die mehr als eine flache Kopie brauchen.","SortableTreeOptions.id":"Standard: `useId()`, stabil zwischen Server- und Client-Rendering. Wird einmal gelesen.","SortableTreeOptions.label":`Der lesbare Name des Baums: Screenreader-Texte nennen ihn statt seiner ID.`,"SortableTreeOptions.data":"Alles, was es über den Baum als Drop-Ziel zu sagen gibt: Events tragen es als `over.data`, solange ein Drag über ihm ist.","SortableTreeOptions.activation":"Wie ein Druck auf die Zeilen dieses Baums einen Drag startet, statt `activation` des Providers (die eigene einer Zeile gewinnt).","SortableTreeOptions.overlay":"Overlay-Komponente für die Zeilen dieses Baums (das eigene `overlay` einer Zeile gewinnt). Ein mitten im Drag umgeschaltetes Ref tauscht sie sofort.","SortableTreeOptions.overOverlay":"Was das Overlay zeigt, während ein Drag, den dieser Baum annimmt, über ihm ist (siehe `SortableListOptions.overOverlay`). Die Prop `to` der Komponente sagt, wohin der Drop verschachtelt würde.","SortableTreeOptions.dropAnimation":"Wie das Overlay landet, wenn ein Drag der Zeilen dieses Baums endet (siehe `SortableListOptions.dropAnimation`).","SortableTreeOptions.overDropAnimation":"Wie das Overlay landet, wenn es in diesen Baum abgelegt wird (siehe `SortableListOptions.overDropAnimation`).","SortableTreeOptions.modifiers":"Modifier für Drags der Zeilen dieses Baums, angewendet nach den `modifiers` des Providers (die eigenen `modifiers` einer Zeile gewinnen): z. B. `[restrictToVerticalAxis]`. Wird beim Start des Drags gelesen. Auch mit gesperrter Achse wird verschachtelt: Die Tiefe ergibt sich dann aus dem Hovern über der Mitte einer Zeile.","SortableTreeOptions.axis":"Beschränkt Drags der Zeilen dieses Baums auf eine Achse (das eigene `axis` einer Zeile gewinnt), nach den Modifiern. Mit `'y'` lassen sich Zeilen weiterhin verschachteln: Die Tiefe ergibt sich dann aus dem Hovern über der Mitte einer Zeile. Wird beim Start des Drags gelesen.","SortableTreeOptions.group":`Listen und Bäume mit demselben Gruppennamen tauschen Elemente aus. Standard: eine eigene Gruppe. Wird einmal gelesen.`,"SortableTreeOptions.acceptMode":"Multi-Drag von Elementen mehrerer Typen: `'all'` (Standard) oder `'some'` müssen angenommen werden (`group.put`).","SortableTreeOptions.indentation":`Pixel horizontaler Versatz pro Tiefenebene. Standard 24.`,"SortableTreeOptions.nesting":`Wie die Tiefe gewählt wird: horizontaler Versatz, Hovern über der Mitte einer Zeile oder beides (Standard).`,"SortableTreeOptions.placeholder":"`'item'` (Standard): Der gezogene Knoten bewegt sich in seiner projizierten Tiefe durch die Zeilen. `'indicator'`: Der Baum bewegt sich nicht; `indicator` (am Baum und am `makeSortableItem` jeder Zeile) sagt, wohin der Drop geht, mit seiner `depth` und seinem `parentKey`, und du zeichnest die Linie. Ein Drop außerhalb bricht dann ab.","SortableTreeOptions.maxDepth":`Größte erlaubte Tiefe (Wurzeln sind 0). Die eigenen Nachkommen der gezogenen Knoten zählen mit.`,"SortableTreeOptions.canNest":"Ob `node` unter `parent` darf; ein Multi-Drag fragt für jeden gezogenen Knoten.","SortableTreeOptions.collapsed":`Schlüssel der Knoten, deren Kinder verborgen sind.`,"SortableTreeOptions.clone":"Erstellt Kopien (`group.pull: 'clone'`, die Modifier-Taste zum Kopieren). Zum Kopieren erforderlich. Gib die Kopie mit ihrem ganzen Teilbaum zurück: Ein kopierter Ordner behält seine Kinder. Die Kopie und jeder ihrer Nachkommen brauchen eigene Schlüssel (gelesen mit `getKey`), wie jeder Knoten eines Baums.","SortableTreeOptions.createItem":"Nimmt einfache ziehbare Elemente von außen an: erstellt den einzufügenden Knoten, an der projizierten Position und Tiefe (`canNest` und `maxDepth` gelten für ihn). Mit der Tastatur holt ein Pfeil in Richtung des Baums das ziehbare Element herein, auf Höhe der Zeile, vor der es eingefügt wird, und die Pfeiltasten bewegen den Knoten dann wie jeden anderen. Bei einem Drag von außerhalb der Seite (`external`) wird es zweimal gefragt, während er gehalten wird und beim Drop (siehe `createItem` der Liste); ein Ordnerknoten mit einem Kind pro Datei fasst mehrere Dateien.","SortableTreeOptions.external":"Nimmt Drags von außerhalb der Seite an: Dateien, Links, Text (siehe `ExternalAccept`), mit `createItem`. Knoten seiner Gruppe, die aus einem anderen Fenster der App hereingezogen werden, kommen als sie selbst hinein. Ein Wert, ein Ref oder ein Getter, live gelesen.","SortableTreeOptions.dropOutside":"Ein Drop außerhalb aller Ziele: die Knoten dort behalten, wo der Platzhalter ist, abbrechen oder sie entfernen. Standard `'placeholder'` (`'cancel'` mit `placeholder: 'indicator'`). Wird beim Drop gelesen.","SortableTreeOptions.animation":"FLIP-Animation dieses Baums; Standard: `animation` des Providers. Ein Wert oder ein Ref (eine Funktion ist eine eigene Animation).","SortableTreeOptions.animateChanges":"Wie bei `SortableListOptions`, für die sichtbaren Zeilen: hinzugefügte, entfernte oder verschobene Knoten und die Zeilen, die ein Knoten beim Auf- oder Zuklappen zeigt oder verbirgt (`collapsed`).","SortableTreeOptions.animateSize":"Die eigene Größe des Baums folgt seinen Zeilen, wie die einer Liste (`animateSize`). Standard `true`.","SortableTreeOptions.autoScroll":"Überschreibt `autoScroll` des Providers für den Scroll-Container dieses Baums. Wird beim Start des Drags gelesen.","SortableTreeOptions.dropzone":"Wie bei `SortableListOptions`: das Element, das Drops für den Baum annimmt, standardmäßig das Element des Baums selbst.","SortableTreeOptions.disabled":"`true`: Seine Zeilen können nicht gezogen werden, und er nimmt keine Elemente an.","SortableTreeOptions.onBeforeDrop":"Wie bei `SortableListOptions`.","SortableTreeOptions.onDrop":"Wie bei `SortableListOptions`: vor dem Schreiben, das `event.preventDefault()` überspringt.",SortableTreeReturn:"Was `makeSortableTree` zurückgibt.","SortableTreeReturn.id":"Die ID des Baums: die Option `id` oder die dafür erzeugte.","SortableTreeReturn.items":`Sichtbare Knoten in Entwurfsreihenfolge; der aktive Knoten trägt seine projizierte Tiefe.`,"SortableTreeReturn.projected":"Wo der aktive Knoten landen würde, `null`, wenn er nicht in diesem Baum ist.","SortableTreeReturn.indicator":"Indikator-Modus: wohin der Drop geht, mit seiner `depth` und seinem `parentKey`; `null`, wenn nicht hier.","SortableTreeReturn.isOver":`Ein Drag ist über dem Baum.`,"SortableTreeReturn.isAccepting":`Etwas wird gezogen, und dieser Baum nimmt es an.`,"SortableTreeReturn.activeKey":`Die Zeile, die ein Virtualizer gemountet lassen muss: der Slot, solange er in diesem Baum ist (der gezogene Knoten, der ausgewählte Knoten, in dem der gegriffene mitfährt, eine Kopie, ein erstellter Knoten), sonst der gezogene Knoten.`,"SortableTreeReturn.activeIndex":"Index von `activeKey` in `items`, -1, wenn er nicht hier ist.","SortableTreeReturn.activeSize":`Größe der gezogenen Zeile beim Start des Drags.`,"SortableTreeReturn.captureLayout":`Animiert Layoutänderungen, die nicht die Bibliothek verursacht hat (z. B. ein erneutes Messen durch einen Virtualizer).`};export{e as default};